```java
public void pump(Session session, OutputStream out) throws IOException {
    int seq = 1;
    boolean started = false;
    try {
        ReportNarrationEvent event;
        while ((event = session.stream().next()) != null) {
            switch (event.type()) {
                case ACCEPTED -> { writeEvent(out, "start", json(payload(session, seq))); started = true; }
                case DELTA -> { seq++; writeEvent(out, "text_delta", json(payload(session, seq, event.delta()))); }
                case COMPLETED -> { seq++; writeEvent(out, "done", json(payload(session, seq))); return; }
                case FAILED -> { seq++; writeError(out, session, seq, codeForFailedEvent(event.failedCode())); return; }
            }
        }
        // defensive: no terminal
        seq++;
        writeError(out, session, seq, ErrorCode.DEPENDENCY_UNAVAILABLE);
    } catch (ReportNarrationException failure) {
        ErrorCode code = failure.kind()==TIMEOUT ? DEPENDENCY_TIMEOUT : DEPENDENCY_UNAVAILABLE;
        log.warn(...);
        seq++;
        writeError(out, session, seq, code);
    } catch (RuntimeException unexpected) {
        log.warn("report narration unexpected stream failure taskId={} exception={}", session.taskId(), unexpected.getClass().getSimpleName());
        try { seq++; writeError(out, session, seq, ErrorCode.INTERNAL); } catch (IOException ignored) { }
    }
}
```

