package cn.yuanxin.mvp.web.assessments.narration;

/**
 * 报告播报下游失败分类：由 HTTP 客户端按"传输/响应形状"归类，供服务层映射到既有错误码。
 * 绝不携带评分值、区域值或密钥。
 *
 * <p>与 {@code gimbalai} 的 {@code GimbalAiFailureKind} 同源范式、刻意不共享：共享需改动已交付
 * 并经审的 {@code web/gimbalai/**}，风险与范围都不可接受；未来若出现第三处再统一抽取。</p>
 */
public enum ReportNarrationFailureKind {

    /** 2xx 但响应不是合法 SSE / 事件缺必填字段 / 终态纪律违规（上游契约违约）。 */
    MALFORMED,

    /** 连接/传输失败，或下游返回非 2xx（含 problem+json）。 */
    UNAVAILABLE,

    /** 连接或读取超时。 */
    TIMEOUT
}

package cn.yuanxin.mvp.web.assessments.narration;

/**
 * 报告播报下游失败（类型化）。<b>绝不</b>承载评分值、区域值、播报文本或 API Key：
 * {@link #getMessage()} 只使用固定安全文案，HTTP 状态/下游业务码仅用于服务端日志。
 *
 * <p>与 {@code gimbalai} 的 {@code GimbalAiException} 同源范式、刻意不共享。</p>
 *
 * <p>任何失败都不得回退为替身或合成文案——上层见此异常必须返回依赖类问题或流内 error 终态。</p>
 */
public class ReportNarrationException extends RuntimeException {

    private final ReportNarrationFailureKind kind;
    private final Integer httpStatus;
    private final String safeCode;

    public ReportNarrationException(ReportNarrationFailureKind kind, String message) {
        this(kind, message, null, null);
    }

    public ReportNarrationException(ReportNarrationFailureKind kind, String message, Integer httpStatus,
                                    String safeCode) {
        super(message);
        this.kind = kind;
        this.httpStatus = httpStatus;
        this.safeCode = safeCode;
    }

    public ReportNarrationFailureKind kind() {
        return kind;
    }

    /** 下游 HTTP 状态；无（传输失败）时为 null。 */
    public Integer httpStatus() {
        return httpStatus;
    }

    /** 下游 problem+json 的 {@code code}（经白名单归一）；仅用于日志。 */
    public String safeCode() {
        return safeCode;
    }
}

package cn.yuanxin.mvp.web.assessments.narration;

import java.util.regex.Pattern;

/**
 * 下游诊断码的安全归一：只允许 {@code ^[A-Z0-9_]{1,64}$}。
 *
 * <p>任何来自下游的不受信字符串（problem+json {@code code}、{@code response.failed.code}）
 * 都必须先经此过滤，才可能进入日志/异常携带字段；不匹配（超长、含控制字符/空格/用户文本、
 * 小写或任意标点）一律归一为 {@code null}，由调用方记为 {@code <none>}。这堵住
 * "下游畸形码把任意载荷反射进日志" 的通道。</p>
 *
 * <p>与 {@code gimbalai} 的 {@code GimbalAiCodes} 同源范式、刻意不共享。</p>
 */
final class ReportNarrationCodes {

    private static final Pattern SAFE_CODE = Pattern.compile("^[A-Z0-9_]{1,64}$");

    private ReportNarrationCodes() {
    }

    /** @return 归一化后的安全码；不匹配返回 {@code null} */
    static String sanitize(String raw) {
        if (raw == null) {
            return null;
        }
        String trimmed = raw.trim();
        return SAFE_CODE.matcher(trimmed).matches() ? trimmed : null;
    }
}

package cn.yuanxin.mvp.web.assessments.narration;

/**
 * 下游 SSE 事件（已由 {@link ReportNarrationSseParser} 校验并归一化）。
 *
 * <p>只允许四个类型：{@code ACCEPTED}（信息性）、{@code DELTA}（{@link #delta()} 为
 * {@code spoken_text} 增量）、{@code COMPLETED}（{@link #spokenText()} 为权威完整文本）、
 * {@code FAILED}（{@link #failedCode()} 仅作诊断）。</p>
 *
 * <p>与 {@code gimbalai} 的 {@code GimbalAiEvent} 同源范式；唯一字段差异是 complete 文本取
 * {@code data.spoken_text} 而非 {@code data.answer.text}（刻意不共享）。</p>
 */
record ReportNarrationEvent(Type type, String delta, String spokenText, String failedCode) {

    enum Type {
        ACCEPTED,
        DELTA,
        COMPLETED,
        FAILED
    }

    static ReportNarrationEvent accepted() {
        return new ReportNarrationEvent(Type.ACCEPTED, null, null, null);
    }

    static ReportNarrationEvent delta(String delta) {
        return new ReportNarrationEvent(Type.DELTA, delta, null, null);
    }

    static ReportNarrationEvent completed(String spokenText) {
        return new ReportNarrationEvent(Type.COMPLETED, null, spokenText, null);
    }

    static ReportNarrationEvent failed(String failedCode) {
        return new ReportNarrationEvent(Type.FAILED, null, null, failedCode);
    }
}

package cn.yuanxin.mvp.web.assessments.narration;

/**
 * SSE 行源：每次返回一行（不含行尾），流结束返回 {@code null}；读取超时/传输失败由
 * 实现抛 {@link ReportNarrationException}。{@link #close()} 必须能解除阻塞的读取并取消下游连接。
 *
 * <p>与 {@code gimbalai} 的 {@code GimbalAiLineSource} 同源范式、刻意不共享。</p>
 */
interface ReportNarrationLineSource extends AutoCloseable {

    /** @return 下一行（不含行尾）；{@code null} 表示流正常结束 */
    String readLine();

    @Override
    void close();
}

package cn.yuanxin.mvp.web.assessments.narration;

/**
 * 已建立的下游 SSE 流句柄（{@link ReportNarrationClient#openStream} 成功返回后）。
 *
 * <p>{@link #next()} 增量返回已校验事件；终态后返回 {@code null}。{@link #close()}
 * 取消下游连接（客户端断开时必须调用）。</p>
 *
 * <p>与 {@code gimbalai} 的 {@code GimbalAiStream} 同源范式、刻意不共享。</p>
 */
public interface ReportNarrationStream extends AutoCloseable {

    /** @return 下一事件；终态后（或已关闭）返回 {@code null} */
    ReportNarrationEvent next();

    @Override
    void close();
}

package cn.yuanxin.mvp.web.assessments.narration;

import org.springframework.boot.context.properties.ConfigurationProperties;

import java.util.ArrayList;
import java.util.List;

/**
 * 报告播报下游配置（{@code app.report-narration.*}）。<b>默认值写在代码里</b>。
 *
 * <p><b>安全</b>：本类只读环境/config；仓库内只允许安全占位（默认空 = 未配置），
 * 绝不硬编码真实服务地址或密钥。缺失校验只输出<b>键名</b>；{@link #toString()}
 * 对 api-key 脱敏。base-url 被允许原样输出（它不是凭据），但仓库内默认必须为空。</p>
 *
 * <p><b>read-timeout 默认 30000ms 的理由</b>：它是 {@code TimeoutLineSource} 的
 * <b>每行/每次 poll</b> 超时（不是整段播报的总时长）。报告播报是长文本生成，逐段下发之间
 * 可能有较长停顿；{@code gimbalai} 的 10s 对其偏短。D 对同一 AI 服务的非流式 assess
 * 默认 30s（{@code dconfig.py:99}），取同一量级更稳妥。部署时可按需调整。</p>
 *
 * <p>与 {@code gimbalai} 的 {@code GimbalAiProperties} 同源范式、刻意不共享
 * （抽共享包必须改动已交付并经审的 {@code web/gimbalai/**}）。</p>
 */
@ConfigurationProperties(prefix = "app.report-narration")
public record ReportNarrationProperties(
        String baseUrl,
        String apiKey,
        Integer connectTimeoutMillis,
        Integer readTimeoutMillis) {

    public static final int DEFAULT_CONNECT_TIMEOUT_MILLIS = 3000;
    public static final int DEFAULT_READ_TIMEOUT_MILLIS = 30000;
    public static final int MIN_TIMEOUT_MILLIS = 1000;

    public ReportNarrationProperties {
        baseUrl = trimToNull(baseUrl);
        apiKey = trimToNull(apiKey);
        connectTimeoutMillis = normalizeTimeout(connectTimeoutMillis, DEFAULT_CONNECT_TIMEOUT_MILLIS);
        readTimeoutMillis = normalizeTimeout(readTimeoutMillis, DEFAULT_READ_TIMEOUT_MILLIS);
    }

    /** 缺失的必填键（仅键名，绝不回显值）。 */
    public List<String> missingRequiredKeys() {
        List<String> missing = new ArrayList<>();
        if (baseUrl == null) {
            missing.add("app.report-narration.base-url");
        }
        if (apiKey == null) {
            missing.add("app.report-narration.api-key");
        }
        return missing;
    }

    /** base-url 去掉结尾斜杠，避免与下游路径拼接出双斜杠。 */
    public String normalizedBaseUrl() {
        if (baseUrl == null) {
            return null;
        }
        return baseUrl.endsWith("/") ? baseUrl.substring(0, baseUrl.length() - 1) : baseUrl;
    }

    @Override
    public String toString() {
        return "ReportNarrationProperties[baseUrl=" + baseUrl
                + ", apiKey=" + (apiKey == null ? "<absent>" : "<redacted>")
                + ", connectTimeoutMillis=" + connectTimeoutMillis
                + ", readTimeoutMillis=" + readTimeoutMillis + "]";
    }

    private static Integer normalizeTimeout(Integer value, int fallback) {
        int normalized = value == null || value <= 0 ? fallback : value;
        return Math.max(MIN_TIMEOUT_MILLIS, normalized);
    }

    private static String trimToNull(String value) {
        if (value == null) {
            return null;
        }
        String trimmed = value.trim();
        return trimmed.isEmpty() ? null : trimmed;
    }
}

package cn.yuanxin.mvp.web.assessments.narration;

import java.math.BigDecimal;
import java.util.List;

/**
 * 已校验、已白名单化的 T05 {@code report_payload} 三项评分（V3 形状）。
 *
 * <p>只含 AI body 所需的三个顶层对象 {@code pores}/{@code spots}/{@code surface_gloss}；
 * 每组只保留白名单四键 {@code score}/{@code severity}/{@code name}/{@code regions}。</p>
 *
 * <p><b>零语义转换</b>：区域名、区域顺序、左右口径、分数高低方向全部原样保留——不改名、
 * 不翻转左右、不做 {@code 100-score} 反转、不重排、不聚合、不补默认值。详见
 * {@link ReportNarrationScoreExtractor} 的裁定说明。</p>
 *
 * <p><b>score 可为 null</b>：原样透传为 JSON {@code null}（既拒绝会破坏合法报告，
 * coerce 成 0 会伪造数据）；其可接受性尚未经真实 AI 确认。severity 同理可为 null。</p>
 *
 * @param pores       毛孔组
 * @param spots       斑点组
 * @param surfaceGloss 表面光泽组（序列化键名为 {@code surface_gloss}）
 */
public record ReportNarrationScores(ScoreGroup pores, ScoreGroup spots, ScoreGroup surfaceGloss) {

    public ReportNarrationScores {
        pores = requireGroup(pores, "pores");
        spots = requireGroup(spots, "spots");
        surfaceGloss = requireGroup(surfaceGloss, "surface_gloss");
    }

    /** 单项评分组：白名单四键 {@code score}/{@code severity}/{@code name}/{@code regions}。 */
    public record ScoreGroup(BigDecimal score, String severity, String name, List<Region> regions) {

        public ScoreGroup {
            if (name == null || name.isBlank()) {
                throw new IllegalArgumentException("report narration score group name is required");
            }
            if (regions == null || regions.isEmpty()) {
                throw new IllegalArgumentException("report narration score group regions are required");
            }
            regions = List.copyOf(regions);
        }
    }

    /**
     * 区域项：白名单四键 {@code region}/{@code name}/{@code score}/{@code severity}。
     * {@code region} 为原始区域码/名（零转换），{@code name} 为原始展示名。
     */
    public record Region(String region, String name, BigDecimal score, String severity) {

        public Region {
            if (region == null || region.isBlank()) {
                throw new IllegalArgumentException("report narration region code is required");
            }
            if (name == null || name.isBlank()) {
                throw new IllegalArgumentException("report narration region name is required");
            }
        }
    }

    private static ScoreGroup requireGroup(ScoreGroup group, String key) {
        if (group == null) {
            throw new IllegalArgumentException("report narration group is required: " + key);
        }
        return group;
    }
}

package cn.yuanxin.mvp.web.assessments.narration;

import cn.yuanxin.mvp.web.error.ApiException;
