 * <p>与 {@code gimbalai} 的 codes/parser 同源纪律、刻意不共享。</p>
 */
final class ReportNarrationScoreExtractor {

    private static final Logger log = LoggerFactory.getLogger(ReportNarrationScoreExtractor.class);

    private static final ObjectMapper MAPPER = new ObjectMapper();

    static final String PAYLOAD_PATH = "report_payload";

    private static final List<String> GROUPS = List.of("pores", "spots", "surface_gloss");
    private static final Set<String> GROUP_KEYS = Set.of("score", "severity", "name", "regions");
    private static final Set<String> REGION_KEYS = Set.of("region", "name", "score", "severity");
    private static final BigDecimal MAX_SCORE = BigDecimal.valueOf(100);

    private static final String MESSAGE =
            "report payload does not satisfy the required three-group score contract";

    private ReportNarrationScoreExtractor() {
    }

    /**
     * @param reportPayload T05 {@code report_payload::text}
     * @return 已校验、已白名单化的三项评分
     * @throws ApiException {@code UNSUPPORTED_CONTRACT}（422）；{@code details} 只含结构性键路径
     */
    static ReportNarrationScores extract(String reportPayload) {
        List<String> missing = new ArrayList<>();
        List<String> invalid = new ArrayList<>();

        JsonNode root = parse(reportPayload, invalid);
        if (root == null) {
            throw fail(missing, invalid);
        }

        Map<String, ReportNarrationScores.ScoreGroup> groups = new LinkedHashMap<>();
        for (String group : GROUPS) {
            ReportNarrationScores.ScoreGroup parsed = group(root, group, missing, invalid);
            if (parsed != null) {
                groups.put(group, parsed);
            }
        }
        if (!missing.isEmpty() || !invalid.isEmpty()) {
            throw fail(missing, invalid);
        }
        return new ReportNarrationScores(
                groups.get("pores"), groups.get("spots"), groups.get("surface_gloss"));
    }

    private static JsonNode parse(String reportPayload, List<String> invalid) {
        if (reportPayload == null || reportPayload.isBlank()) {
            invalid.add(PAYLOAD_PATH);
            return null;
        }
        try {
            JsonNode root = MAPPER.readTree(reportPayload);
            if (root == null || !root.isObject()) {
                invalid.add(PAYLOAD_PATH);
                return null;
            }
            return root;
        } catch (Exception unparseable) {
            invalid.add(PAYLOAD_PATH);
            return null;
        }
    }

    private static ReportNarrationScores.ScoreGroup group(JsonNode root, String groupName,
                                                          List<String> missing, List<String> invalid) {
        JsonNode node = root.get(groupName);
        if (node == null) {
            missing.add(groupName);
            return null;
        }
        if (!node.isObject()) {
            invalid.add(groupName);
            return null;
        }
        warnUnknownKeys(groupName, node, GROUP_KEYS);

        int invalidBefore = invalid.size();
        BigDecimal score = readScore(node.get("score"), groupName + ".score", invalid);
        String severity = readSeverity(node.get("severity"), groupName + ".severity", invalid);
        String name = readName(node.get("name"), groupName + ".name", invalid);
        List<ReportNarrationScores.Region> regions =
                readRegions(node.get("regions"), groupName, invalid);
        if (invalid.size() != invalidBefore || name == null || regions == null) {
            return null;
        }
        return new ReportNarrationScores.ScoreGroup(score, severity, name, regions);
    }

    private static List<ReportNarrationScores.Region> readRegions(JsonNode node, String groupName,
                                                                  List<String> invalid) {
        if (node == null || !node.isArray() || node.isEmpty()) {
            invalid.add(groupName + ".regions");
            return null;
        }
        List<ReportNarrationScores.Region> regions = new ArrayList<>();
        for (int i = 0; i < node.size(); i++) {
            JsonNode region = node.get(i);
            String path = groupName + ".regions[" + i + "]";
            if (!region.isObject()) {
                invalid.add(path);
                continue;
            }
            warnUnknownKeys(path, region, REGION_KEYS);
            String regionCode = readName(region.get("region"), path + ".region", invalid);
            String regionName = readName(region.get("name"), path + ".name", invalid);
            BigDecimal regionScore = readScore(region.get("score"), path + ".score", invalid);
            String regionSeverity = readSeverity(region.get("severity"), path + ".severity", invalid);
            if (regionCode != null && regionName != null) {
                regions.add(new ReportNarrationScores.Region(
                        regionCode, regionName, regionScore, regionSeverity));
            }
        }
        if (regions.isEmpty()) {
            invalid.add(groupName + ".regions");
            return null;
        }
        return regions;
    }

    /** {@code score}：number 且 0–100，或 null；缺失视为 null。其它类型/越界 → invalid。 */
    private static BigDecimal readScore(JsonNode node, String path, List<String> invalid) {
        if (node == null || node.isNull()) {
            return null;
        }
        if (!node.isNumber()) {
            invalid.add(path);
            return null;
        }
        BigDecimal value = node.decimalValue();
        if (value.compareTo(BigDecimal.ZERO) < 0 || value.compareTo(MAX_SCORE) > 0) {
            invalid.add(path);
            return null;
        }
        return value;
    }

    /** {@code severity}：非空白 string，或 null；缺失视为 null。其它类型/空白 → invalid。 */
    private static String readSeverity(JsonNode node, String path, List<String> invalid) {
        if (node == null || node.isNull()) {
            return null;
        }
        if (!node.isTextual() || node.asText().isBlank()) {
            invalid.add(path);
            return null;
        }
        return node.asText();
    }

    /** {@code name}/{@code region}：必需、非空白 string。 */
    private static String readName(JsonNode node, String path, List<String> invalid) {
        if (node == null || !node.isTextual() || node.asText().isBlank()) {
            invalid.add(path);
            return null;
        }
        return node.asText();
    }

    /** 只记被丢弃的<b>键名</b>（组/区域路径 + 键名）；绝不记录值。 */
    private static void warnUnknownKeys(String path, JsonNode object, Set<String> allowed) {
        object.fieldNames().forEachRemaining(key -> {
            if (!allowed.contains(key)) {
                log.warn("report narration payload dropped unknown key path={}.{}", path, key);
            }
        });
    }

    private static ApiException fail(List<String> missing, List<String> invalid) {
        Map<String, Object> details = new LinkedHashMap<>();
        if (!missing.isEmpty()) {
            details.put("missing", List.copyOf(missing));
        }
        if (!invalid.isEmpty()) {
            details.put("invalid", List.copyOf(invalid));
        }
        return new ApiException(ErrorCode.UNSUPPORTED_CONTRACT, MESSAGE, details);
    }
}

package cn.yuanxin.mvp.web.assessments.narration;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Set;

/**
 * 下游 {@code /internal/v1/weijing/reports/assess:stream} 的<b>增量</b> SSE 解析器
 * （严格 fail-closed）。与 {@code gimbalai} 的 {@code GimbalAiSseParser} 同源范式、刻意不共享；
 * 唯一字段差异是 {@code response.completed} 取 {@code data.spoken_text}（gimbalai 取
 * {@code data.answer.text}）。</p>
 *
 * <p>只接受四个事件：{@code response.accepted}（信息性）、{@code response.delta}
 * （按序累加 {@code data.delta} 即 {@code spoken_text} 增量）、{@code response.completed}
 * （成功终态；{@code data.spoken_text} 权威）、{@code response.failed}（终态失败，
 * {@code code} 仅作诊断）。</p>
 *
 * <p><b>fail-closed</b>：未知事件、事件后又有事件（含重复终态）、缺终态（EOF）、
 * 事件缺 data、data 非 JSON/非对象、{@code response.delta} 缺文本、
 * {@code response.completed} 缺非空 {@code spoken_text}、事件数/累计增量越界 → 抛
 * {@link ReportNarrationException}（{@code MALFORMED}）。读取超时/传输失败由行源抛
 * {@code TIMEOUT}/{@code UNAVAILABLE}。绝不返回部分/合成文案。</p>
 *
 * <p><b>两条流纪律裁定（§6.3）</b>：</p>
 * <ol>
 *   <li><b>零 delta 即失败</b>：{@code completed} 到达时一个 delta 都没发过 → {@code MALFORMED}，
 *       外部只发一个 {@code error} 终态。理由：设备将朗读不到任何内容却收到 {@code done}，那是假成功。</li>
 *   <li><b>拼接与 {@code spoken_text} 不一致只告警不失败</b>：累计 delta 与
 *       {@code completed.spoken_text} 不等时，{@code log.warn} 记录<b>两者的字符长度</b>
 *       （绝不记录内容），仍正常发 {@code done}。理由：文本已真实逐段送达客户端，AI 自身摘要与
 *       其增量不一致属下游内部矛盾；在已送达全部文本后再发 {@code error} 会让设备在朗读完毕后显示失败。</li>
 * </ol>
 *
 * <p>终止策略：遇到终态事件后，仍继续读到流结束以检出"终态后事件/重复终态"；此类违规一律
 * malformed。终态事件在流结束（EOF）后才可被消费，从而保证恰一个终态。</p>
 *
 * <p><b>有界</b>（与行源的 64 KiB 单行上限叠加）：单事件累积 data 上限
 * {@value #MAX_EVENT_DATA_CHARS} 字符、事件数上限 {@value #MAX_EVENTS}、累计增量与
 * {@code spoken_text} 上限 {@value #MAX_ACCUMULATED_CHARS} 字符——任一越界即 {@code MALFORMED}，
 * 绝不无界累积。</p>
 */
final class ReportNarrationSseParser implements AutoCloseable {

    private static final Logger log = LoggerFactory.getLogger(ReportNarrationSseParser.class);

    private static final ObjectMapper MAPPER = new ObjectMapper();

    private static final Set<String> EVENTS = Set.of(
            "response.accepted", "response.delta", "response.completed", "response.failed");

    /** 单次流事件的硬上限（防无界事件流）。 */
    static final int MAX_EVENTS = 10_000;
    /** 单事件累积 data 字符上限（多行 data 也受限）。 */
    static final int MAX_EVENT_DATA_CHARS = 256 * 1024;
    /** 累计 delta 与 completed.spoken_text 字符上限。 */
    static final int MAX_ACCUMULATED_CHARS = 200_000;

    private final ReportNarrationLineSource source;
    private final Deque<ReportNarrationEvent> ready = new ArrayDeque<>();

    private boolean done;
    private boolean terminalSeen;
    private ReportNarrationEvent pendingTerminal;

    private String eventName;
    private final StringBuilder data = new StringBuilder();
    private boolean hasData;
    private int eventCount;
    private int accumulatedChars;
    private boolean deltaSeen;

    ReportNarrationSseParser(ReportNarrationLineSource source) {
        this.source = source;
    }

    /**
     * 下一个已校验事件；流在终态后正常结束返回 {@code null}。
     *
     * @throws ReportNarrationException 协议违规（MALFORMED）或读取超时/传输失败（TIMEOUT/UNAVAILABLE）
     */
    ReportNarrationEvent next() {
        if (!ready.isEmpty()) {
            return ready.poll();
        }
        if (done) {
            return null;
        }
        while (ready.isEmpty() && !done) {
            String line = source.readLine();
            if (line == null) {
                flushBlock();
                if (!terminalSeen) {
                    throw malformed("stream ended without a terminal event");
                }
                if (pendingTerminal != null) {
                    ready.add(pendingTerminal);
                    pendingTerminal = null;
                }
                done = true;
                break;
            }
            if (line.isEmpty()) {
                flushBlock();
                continue;
            }
            if (line.startsWith(":")) {
                continue; // SSE 注释行 / heartbeat：忽略
            }
            int colon = line.indexOf(':');
            String field = colon < 0 ? line : line.substring(0, colon);
            String value = colon < 0 ? "" : line.substring(colon + 1);
            if (value.startsWith(" ")) {
                value = value.substring(1);
            }
            switch (field) {
                case "event" -> eventName = value;
                case "data" -> {
                    if (hasData) {
                        data.append('\n');
                    }
                    data.append(value);
                    hasData = true;
                    if (data.length() > MAX_EVENT_DATA_CHARS) {
                        throw malformed("stream event data exceeded the maximum length");
                    }
                }
                default -> {
                    // id/retry/未知字段：忽略；绝不断点续传。
                }
            }
        }
        return ready.poll();
    }

    private void flushBlock() {
        String name = eventName;
        boolean hadData = hasData;
        String payload = hasData ? data.toString() : null;
        eventName = null;
        data.setLength(0);
        hasData = false;
        if (name == null && !hadData) {
            return;
        }
        eventCount++;
        if (eventCount > MAX_EVENTS) {
            throw malformed("stream exceeded the maximum event count");
        }
        if (name == null) {
            throw malformed("stream data without an event name");
        }
        if (!EVENTS.contains(name)) {
            throw malformed("unknown stream event");
        }
        if (terminalSeen) {
            throw malformed("stream event after the terminal event");
        }
        if (payload == null) {
            throw malformed("stream event missing data");
        }
        JsonNode root;
        try {
            root = MAPPER.readTree(payload);
        } catch (Exception unparseable) {
            throw malformed("stream event data is not valid JSON");
        }
        if (root == null || !root.isObject()) {
            throw malformed("stream event data is not a JSON object");
        }
        switch (name) {
            case "response.accepted" -> ready.add(ReportNarrationEvent.accepted());
            case "response.delta" -> {
                JsonNode delta = root.get("delta");
                if (delta == null || !delta.isTextual()) {
                    throw malformed("response.delta event missing a textual 'delta'");
                }
                accumulatedChars += delta.asText().length();
                if (accumulatedChars > MAX_ACCUMULATED_CHARS) {
                    throw malformed("accumulated delta exceeded the maximum length");
                }
                deltaSeen = true;
                ready.add(ReportNarrationEvent.delta(delta.asText()));
            }
            case "response.completed" -> {
                JsonNode text = root.get("spoken_text");
                if (!text.isTextual() || text.asText().isBlank()) {
                    throw malformed("response.completed event missing a non-blank spoken_text");
                }
                if (text.asText().length() > MAX_ACCUMULATED_CHARS) {
                    throw malformed("response.completed spoken_text exceeded the maximum length");
                }
                if (!deltaSeen) {
                    throw malformed("response.completed arrived without any delta");
                }
                if (accumulatedChars != text.asText().length()) {
                    // 绝不记录内容：只记两者字符长度。
                    log.warn("report narration spoken_text mismatch accumulatedChars={} completedChars={}",
                            accumulatedChars, text.asText().length());
                }
                terminalSeen = true;
                pendingTerminal = ReportNarrationEvent.completed(text.asText());
            }
            case "response.failed" -> {
                String code = root.path("code").isTextual()
                        ? ReportNarrationCodes.sanitize(root.path("code").asText()) : null;
                terminalSeen = true;
                pendingTerminal = ReportNarrationEvent.failed(code);
            }
            default -> throw malformed("unknown stream event");
        }
    }

    @Override
    public void close() {
        source.close();
    }

    private static ReportNarrationException malformed(String detail) {
        return new ReportNarrationException(ReportNarrationFailureKind.MALFORMED,
                "report narration downstream returned a malformed stream: " + detail, null, null);
    }
}

package cn.yuanxin.mvp.web.assessments.narration;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.BufferedInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.BigDecimal;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.net.http.HttpTimeoutException;
import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.time.Duration;
import java.util.UUID;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * 报告播报下游客户端（JDK {@link HttpClient}；<b>SSE 流式</b>；无状态、无重试回退）。
 *
 * <p>固定契约（对 {@code POST {base}/internal/v1/weijing/reports/assess:stream}）：</p>
 * <ul>
 *   <li>Header：{@code X-Service-Name=medical-platform}、{@code X-API-Key}（配置）、
 *       {@code X-Request-Id}（每次调用新生成）、{@code Idempotency-Key}（<b>每次调用全新</b>，
 *       故客户端重试会产生<b>新评估</b>；本增量无本地幂等存储）、{@code X-Protocol-Version=1.0}、
 *       {@code traceparent}（W3C）、{@code Accept: text/event-stream}（<b>不是</b>
 *       {@code application/json}）、{@code Content-Type: application/json}；
 *       <b>绝不转发</b>云台的 {@code Authorization}/{@code Cookie}/任何入站头，
 *       也<b>不发送</b> Last-Event-ID（绝不续传）；</li>
 *   <li>Body：<b>恰好</b> {@code {"pores":{...},"spots":{...},"surface_gloss":{...}}}，
 *       每组只含白名单四键 {@code score}/{@code severity}/{@code name}/{@code regions}；
 *       不加 {@code report_id}/{@code algorithm_version}/{@code protocol_version}/{@code use_case}/
 *       {@code input} 等任何额外键；{@code score}/{@code severity} 为 null 时原样序列化为 JSON null；</li>
 *   <li>预流：非 2xx → {@code UNAVAILABLE}；连接失败 → {@code UNAVAILABLE}；预流超时 → {@code TIMEOUT}；
 *       流内：由 {@link ReportNarrationSseParser} 增量严格校验，读取超时 → {@code TIMEOUT}，
 *       传输/EOF 违规 → {@code MALFORMED}/{@code UNAVAILABLE}。</li>
 * </ul>
 *
 * <p><b>有界性（防挂死/OOM）</b>：</p>
 * <ul>
 *   <li>预流以 {@code read-timeout} 约束"响应头到达"；超时/中断会 {@code cancel(true)} 该 future，
 *       并在迟到的响应上尽力关闭 body，避免交换滞留；</li>
 *   <li>非 2xx problem body 的读取上限 {@value #MAX_PROBLEM_BODY_BYTES} 字节、期限
 *       {@code min(read-timeout, }{@value #PROBLEM_BODY_TIMEOUT_MILLIS}{@code ms)}；超限/超时即放弃
 *       解析（code 记为 null），openStream 总能及时返回 JSON problem；</li>
 *   <li>流内行源：有界队列（容量 {@value TimeoutLineSource#QUEUE_CAPACITY}，{@code put} 反压）、
 *       单行硬上限 {@value TimeoutLineSource#MAX_LINE_BYTES} 字节（超出 → {@code MALFORMED}）、
 *       取消/超时先关<b>原始</b> InputStream（不取 BufferedReader 锁）再中断并 {@code join} 有界；
 *       终态文本长度上限见 {@link ReportNarrationSseParser#MAX_ACCUMULATED_CHARS}。</li>
 * </ul>
 *
 * <p><b>绝不</b>回退到一次性接口；<b>绝不</b>合成文案。</p>
 *
 * <p><b>日志</b>：只记下游 requestId / HTTP 状态 / 经 {@link ReportNarrationCodes} 归一的安全码 /
 * 失败分类；绝不记 API Key、评分值、区域值、{@code spoken_text}、SSE 原文。</p>
 *
 * <p>与 {@code gimbalai} 的 {@code HttpGimbalAiClient} 同源范式、刻意不共享。</p>
 */
public class HttpReportNarrationClient implements ReportNarrationClient {

    private static final Logger log = LoggerFactory.getLogger(HttpReportNarrationClient.class);

    static final String SERVICE_NAME = "medical-platform";
    static final String PROTOCOL_VERSION = "1.0";
    static final String REPORTS_STREAM_PATH = "/internal/v1/weijing/reports/assess:stream";

    /** 非 2xx problem body 的读取上限（字节）。 */
    static final int MAX_PROBLEM_BODY_BYTES = 8 * 1024;
    /** 非 2xx problem body 的读取期限上限（毫秒），与 read-timeout 取较小值。 */
    static final long PROBLEM_BODY_TIMEOUT_MILLIS = 2000;

    private static final SecureRandom RANDOM = new SecureRandom();

    private final HttpClient httpClient;
    private final ObjectMapper objectMapper;
    private final URI endpoint;
    private final String apiKey;
    private final long readTimeoutMillis;

    public HttpReportNarrationClient(ReportNarrationProperties properties, ObjectMapper objectMapper) {
        this(properties, objectMapper, HttpClient.newBuilder()
                .connectTimeout(Duration.ofMillis(properties.connectTimeoutMillis()))
                .build());
    }

    /** 测试用构造器：注入自定义 HttpClient（如指向本地 stub 的连接池）。 */
    HttpReportNarrationClient(ReportNarrationProperties properties, ObjectMapper objectMapper,
                              HttpClient httpClient) {
        this.objectMapper = objectMapper;
        this.httpClient = httpClient;
        this.endpoint = URI.create(properties.normalizedBaseUrl() + REPORTS_STREAM_PATH);
        this.apiKey = properties.apiKey();
        this.readTimeoutMillis = properties.readTimeoutMillis();
    }

    @Override
    public ReportNarrationStream openStream(ReportNarrationScores scores) {
        String requestId = UUID.randomUUID().toString();
        String idempotencyKey = UUID.randomUUID().toString();
        String traceparent = newTraceparent();

        HttpRequest request = HttpRequest.newBuilder(endpoint)
                .header("X-Service-Name", SERVICE_NAME)
                .header("X-API-Key", apiKey)
                .header("X-Request-Id", requestId)
                .header("Idempotency-Key", idempotencyKey)
                .header("X-Protocol-Version", PROTOCOL_VERSION)
                .header("traceparent", traceparent)
                .header("Accept", "text/event-stream")
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(
                        buildBody(scores), StandardCharsets.UTF_8))
                .build();

        HttpResponse<InputStream> response = sendForHeaders(request, requestId);
        int status = response.statusCode();
        if (status < 200 || status >= 300) {
            String safeCode = ReportNarrationCodes.sanitize(readProblemCode(response.body()));
            log.warn("report narration downstream non-2xx requestId={} status={} code={}",
                    requestId, status, safeCode == null ? "<none>" : safeCode);
            closeQuietly(response.body());
            throw new ReportNarrationException(ReportNarrationFailureKind.UNAVAILABLE,
                    "report narration downstream returned a non-success status", status, safeCode);
        }
        ReportNarrationSseParser parser = new ReportNarrationSseParser(
                new TimeoutLineSource(response.body(), readTimeoutMillis));
        log.info("report narration downstream stream opened requestId={} status={}", requestId, status);
        return new ReportNarrationStream() {
            @Override
            public ReportNarrationEvent next() {
                return parser.next();
            }

            @Override
            public void close() {
                parser.close();
            }
        };
    }

    /**
     * 预流：以 read-timeout 约束"响应头到达"。超时/中断时 {@code cancel(true)} 并尽力关闭迟到
     * 响应体（避免交换滞留）；预流超时 → TIMEOUT，连接失败 → UNAVAILABLE。
     */
    private HttpResponse<InputStream> sendForHeaders(HttpRequest request, String requestId) {
        CompletableFuture<HttpResponse<InputStream>> future =
                httpClient.sendAsync(request, HttpResponse.BodyHandlers.ofInputStream());
        try {
            return future.get(readTimeoutMillis, TimeUnit.MILLISECONDS);
        } catch (TimeoutException timeout) {
            cancelAndDrain(future);
            log.warn("report narration downstream pre-stream timeout requestId={}", requestId);
            throw new ReportNarrationException(ReportNarrationFailureKind.TIMEOUT,
                    "report narration downstream timed out before streaming");
        } catch (InterruptedException interrupted) {
            cancelAndDrain(future);
            Thread.currentThread().interrupt();
            throw new ReportNarrationException(ReportNarrationFailureKind.UNAVAILABLE,
                    "report narration downstream call was interrupted");
        } catch (ExecutionException failure) {
            Throwable cause = failure.getCause();
            if (cause instanceof HttpTimeoutException) {
                throw new ReportNarrationException(ReportNarrationFailureKind.TIMEOUT,
                        "report narration downstream timed out before streaming");
            }
            log.warn("report narration downstream transport failure requestId={} exception={}",
                    requestId, cause == null ? "unknown" : cause.getClass().getSimpleName());
            throw new ReportNarrationException(ReportNarrationFailureKind.UNAVAILABLE,
                    "report narration downstream transport failure");
        }
    }

    /** 取消预流 future，并在其"迟到完成"时尽力关闭响应体。 */
    private static void cancelAndDrain(CompletableFuture<?> future) {
        future.cancel(true);
        future.whenComplete((value, error) -> {
            if (value instanceof HttpResponse<?> response
                    && response.body() instanceof InputStream body) {
                closeQuietly(body);
            }
        });
    }

    /**
     * 有界读取非 2xx body 并返回其中的 {@code code} 文本（未归一）。
     *
     * <p>上限 {@value #MAX_PROBLEM_BODY_BYTES} 字节、期限 {@code min(read-timeout,
     * }{@value #PROBLEM_BODY_TIMEOUT_MILLIS}{@code ms)}；超限只解析已读到的前缀，超时/异常返回
     * {@code null}。无论结果如何都关闭 body，保证 openStream 及时返回。</p>
     */
    private String readProblemCode(InputStream body) {
        if (body == null) {
            return null;
        }
        long deadlineMillis = Math.min(readTimeoutMillis, PROBLEM_BODY_TIMEOUT_MILLIS);
        ExecutorService executor = Executors.newSingleThreadExecutor(runnable -> {
            Thread thread = new Thread(runnable, "report-narration-problem-body");
            thread.setDaemon(true);
            return thread;
        });
        try {
            Future<String> future = executor.submit(
                    () -> new String(body.readNBytes(MAX_PROBLEM_BODY_BYTES), StandardCharsets.UTF_8));
            String json = future.get(deadlineMillis, TimeUnit.MILLISECONDS);
            try {
                JsonNode node = objectMapper.readTree(json).path("code");
                return node.isTextual() ? node.asText() : null;
            } catch (Exception unparseable) {
                return null;
            }
        } catch (Exception bounded) {
            return null;
        } finally {
            closeQuietly(body); // 解除工作线程的阻塞读
            executor.shutdownNow();
        }
    }

    private static void closeQuietly(InputStream body) {
        if (body == null) {
            return;
        }
        try {
            body.close();
        } catch (IOException ignored) {
            // best effort
        }
    }

    /**
     * 组装 AI body：顶层<b>恰好</b>三个键（pores、spots、surface_gloss，顺序固定），
     * 每组恰好白名单四键，使用 {@code objectMapper}（不手拼字符串）。
     */
    private String buildBody(ReportNarrationScores scores) {
        try {
            ObjectNode root = objectMapper.createObjectNode();
            root.set("pores", groupNode(scores.pores()));
            root.set("spots", groupNode(scores.spots()));
            root.set("surface_gloss", groupNode(scores.surfaceGloss()));
            return objectMapper.writeValueAsString(root);
        } catch (Exception encoding) {
            throw new ReportNarrationException(ReportNarrationFailureKind.UNAVAILABLE,
                    "report narration downstream request could not be encoded");
        }
    }

    private ObjectNode groupNode(ReportNarrationScores.ScoreGroup group) {
        ObjectNode node = objectMapper.createObjectNode();
        putScore(node, "score", group.score());
        putSeverity(node, "severity", group.severity());
        node.put("name", group.name());
        ArrayNode regions = objectMapper.createArrayNode();
        for (ReportNarrationScores.Region region : group.regions()) {
            ObjectNode regionNode = objectMapper.createObjectNode();
            regionNode.put("region", region.region());
            regionNode.put("name", region.name());
            putScore(regionNode, "score", region.score());
            putSeverity(regionNode, "severity", region.severity());
            regions.add(regionNode);
        }
        node.set("regions", regions);
        return node;
    }

    /** score 为 null 时原样写 JSON null（绝不 coerce 成 0）。 */
    private static void putScore(ObjectNode node, String field, BigDecimal score) {
        if (score == null) {
            node.putNull(field);
        } else {
            node.put(field, score);
        }
    }

    /** severity 为 null 时原样写 JSON null。 */
    private static void putSeverity(ObjectNode node, String field, String severity) {
        if (severity == null) {
            node.putNull(field);
        } else {
            node.put(field, severity);
        }
    }

    private static String newTraceparent() {
        return "00-" + randomHex(16) + "-" + randomHex(8) + "-01";
    }

    private static String randomHex(int byteCount) {
        byte[] bytes = new byte[byteCount];
        RANDOM.nextBytes(bytes);
        StringBuilder builder = new StringBuilder(byteCount * 2);
        for (byte b : bytes) {
            builder.append(Character.forDigit((b >> 4) & 0xF, 16));
            builder.append(Character.forDigit(b & 0xF, 16));
        }
        return builder.toString();
    }

    /**
     * 带单次读取超时的 SSE 行源（有界、可取消）。
     *
     * <p>工作线程从<b>原始</b> {@code InputStream} 逐字节读取（经 {@link BufferedInputStream}
     * 吞吐优化），单行硬上限 {@value #MAX_LINE_BYTES} 字节（超出 → {@code MALFORMED}），
     * 以容量 {@value #QUEUE_CAPACITY} 的有界队列 + 可中断 {@code put} 形成反压。</p>
     *
     * <p><b>取消/超时</b>：先关闭<b>原始</b>流（其 {@code close()} 不取 {@code BufferedReader}
     * 的锁，可直接解除工作线程的 socket 阻塞读），再 {@code interrupt()} 并 {@code join}
     * （上限 {@value #CLOSE_JOIN_MILLIS} ms），绝不以 {@code BufferedReader.close()} 作为解阻塞手段。
     * 与 {@code gimbalai} 的 {@code TimeoutLineSource} 同源范式、刻意不共享。</p>
     */
    private static final class TimeoutLineSource implements ReportNarrationLineSource {

        private static final Object EOF = new Object();
        /** 有界队列容量（反压）。 */
        static final int QUEUE_CAPACITY = 1024;
        /** 单行原始字节硬上限。 */
        static final int MAX_LINE_BYTES = 64 * 1024;
        /** close() 等待工作线程退出的上限。 */
        static final long CLOSE_JOIN_MILLIS = 500;

        private final InputStream raw;
        private final BufferedInputStream buffered;
        private final java.io.PushbackInputStream input;
        private final long timeoutMillis;
        private final BlockingQueue<Object> queue = new ArrayBlockingQueue<>(QUEUE_CAPACITY);
        private final AtomicBoolean closed = new AtomicBoolean();
        private final Thread worker;

        TimeoutLineSource(InputStream raw, long timeoutMillis) {
            this.raw = raw;
            this.buffered = new BufferedInputStream(raw, 8192);
            this.input = new java.io.PushbackInputStream(buffered, 1);
            this.timeoutMillis = timeoutMillis;
            this.worker = new Thread(this::pump, "report-narration-sse-reader");
            this.worker.setDaemon(true);
            this.worker.start();
        }

        private void pump() {
            try {
                String line;
                while ((line = readBoundedLine()) != null) {
                    if (closed.get()) {
                        return;
                    }
                    enqueue(line);
                }
                if (!closed.get()) {
                    enqueue(EOF);
                }
            } catch (LineTooLongException tooLong) {
                if (!closed.get()) {
                    enqueue(new ReportNarrationException(ReportNarrationFailureKind.MALFORMED,
                            "report narration downstream SSE line exceeded the maximum length"));
                }
            } catch (IOException io) {
                if (!closed.get()) {
                    enqueue(io);
                }
            }
        }

        /** 逐字节读到行终止符（\n / \r\n / \r）或 EOF；超 {@value #MAX_LINE_BYTES} 抛异常。 */
        private String readBoundedLine() throws IOException {
            ByteArrayOutputStream buffer = new ByteArrayOutputStream();
            int b;
            while ((b = input.read()) != -1) {
                if (b == '\n') {
                    return new String(buffer.toByteArray(), StandardCharsets.UTF_8);
                }
                if (b == '\r') {
                    int next = input.read();
                    if (next != -1 && next != '\n') {
                        input.unread(next);
                    }
                    return new String(buffer.toByteArray(), StandardCharsets.UTF_8);
                }
                if (buffer.size() >= MAX_LINE_BYTES) {
                    throw new LineTooLongException();
                }
                buffer.write(b);
            }
            if (buffer.size() == 0) {
                return null;
            }
            return new String(buffer.toByteArray(), StandardCharsets.UTF_8);
        }

        private void enqueue(Object item) {
            try {
                queue.put(item); // 满时阻塞形成反压
            } catch (InterruptedException interrupted) {
                Thread.currentThread().interrupt();
            }
        }

        @Override
        public String readLine() {
            Object item;
            try {
                item = queue.poll(timeoutMillis, TimeUnit.MILLISECONDS);
            } catch (InterruptedException interrupted) {
                Thread.currentThread().interrupt();
                close();
                throw new ReportNarrationException(ReportNarrationFailureKind.UNAVAILABLE,
                        "report narration downstream read interrupted");
            }
            if (item == null) {
                close();
                throw new ReportNarrationException(ReportNarrationFailureKind.TIMEOUT,
                        "report narration downstream stream read timed out");
            }
            if (item == EOF) {
                return null;
            }
            if (item instanceof ReportNarrationException failure) {
                throw failure;
            }
            if (item instanceof IOException) {
                throw new ReportNarrationException(ReportNarrationFailureKind.UNAVAILABLE,
                        "report narration downstream stream transport failure");
            }
            return (String) item;
        }

        @Override
        public void close() {
            if (!closed.compareAndSet(false, true)) {
                return;
            }
            // 先关原始流：其 close() 不取 BufferedReader 锁，直接解除工作线程的阻塞读。
            closeQuietly(raw);
            worker.interrupt();
            try {
                worker.join(CLOSE_JOIN_MILLIS);
            } catch (InterruptedException interrupted) {
                Thread.currentThread().interrupt();
            }
        }
    }

    /** 单行超出硬上限的内部信号（不对外）。 */
    private static final class LineTooLongException extends IOException {
        LineTooLongException() {
            super("line too long");
        }
    }
}

package cn.yuanxin.mvp.web.assessments.narration;

import cn.yuanxin.mvp.web.config.AppProperties;
import cn.yuanxin.mvp.web.config.NonProductionCondition;
import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.env.Environment;

import java.util.List;

/**
 * 报告播报客户端装配。优先级（与 B/C/D 既有 provider 约定一致）：
 * <pre>app.providers.mode=disabled （能力显式关闭） &gt; app.report-narration 配置是否齐备</pre>
 *
 * <ul>
 *   <li>{@code mode=disabled} → 停机占位：调用即 503 DEPENDENCY_UNAVAILABLE
 *       （沿 {@code DisabledProvidersConfig} 占位接线语义）；</li>
 *   <li>配置齐备 → 真实 {@link HttpReportNarrationClient}；</li>
 *   <li>配置缺失且<b>非生产</b> → 停机占位（运行时 503，应用仍可启动）；</li>
 *   <li>配置缺失且<b>生产信号</b>（{@code app.env=production} 或 prod profile）→
 *       启动失败（fail-closed；消息只列键名，绝不回显值）。</li>
 * </ul>
 *
 * <p>无替身回退：任何失败路径都不会产生合成文案。</p>
 *
 * <p>与 {@code gimbalai} 的 {@code GimbalAiProvidersConfig} 同源范式、刻意不共享。</p>
 */
@Configuration
@EnableConfigurationProperties(ReportNarrationProperties.class)
public class ReportNarrationProvidersConfig {

    @Bean
    public ReportNarrationClient reportNarrationClient(ReportNarrationProperties properties,
                                                       Environment environment,
                                                       ObjectMapper objectMapper) {
        return createClient(properties, environment, objectMapper);
    }

    /**
     * 可单测的工厂：按 mode/env/配置选择真实客户端或停机占位。
     * 缺失键仅在消息中列键名，绝不回显值。
     */
    static ReportNarrationClient createClient(ReportNarrationProperties properties,
                                              Environment environment,
                                              ObjectMapper objectMapper) {
        String mode = new AppProperties.Providers(
                environment.getProperty("app.providers.mode")).mode();
        if ("disabled".equals(mode)) {
            return unavailable("report narration capability disabled by configuration");
        }
        List<String> missing = properties.missingRequiredKeys();
        if (missing.isEmpty()) {
            return new HttpReportNarrationClient(properties, objectMapper);
        }
        if (!NonProductionCondition.isNonProduction(environment)) {
            throw new IllegalStateException(
                    "production fail-closed: app.report-narration missing required config keys " + missing
                            + " (values are never logged); configure base-url/api-key or set"
                            + " app.providers.mode=disabled");
        }
        return unavailable("report narration capability is not configured");
    }

    private static ReportNarrationClient unavailable(String reason) {
        return scores -> {
            throw new ApiException(ErrorCode.DEPENDENCY_UNAVAILABLE, reason);
        };
    }
}

package cn.yuanxin.mvp.web.assessments.narration;

import cn.yuanxin.mvp.web.assessments.AssessmentReadService;
import cn.yuanxin.mvp.web.assessments.AssessmentRepository;
import cn.yuanxin.mvp.web.assessments.dto.AssessmentTaskView;
import cn.yuanxin.mvp.web.auth.PrincipalContext;
import cn.yuanxin.mvp.web.auth.PrincipalType;
import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.UUID;

/**
 * 报告播报业务入口：门禁 → 读 T05 {@code report_payload} → 校验 → 开下游流 → {@code pump}。
 *
 * <p><b>预流顺序</b>（请求线程，任一失败在建立 SSE 之前抛 {@link ApiException}，
 * 由 {@link ReportNarrationStreamErrorAdvice} 渲染为 JSON 错误信封）：</p>
 * <ol>
 *   <li>仅 {@link PrincipalType#GIMBAL}；APP 主体在<b>打开下游之前</b>拒绝（403 CALLER_NOT_ALLOWED）；</li>
 *   <li>复用 {@link AssessmentReadService#getTask} 既有门禁（404 {@code RESOURCE_NOT_VISIBLE} /
 *       409 {@code TASK_REPLACED}）——<b>不复制、不重写</b>门禁逻辑；</li>
 *   <li>报告未就绪（{@code reportId} 为空）→ 404 {@code RESOURCE_NOT_VISIBLE}；</li>
 *   <li>读 {@code report_payload}：<b>只读复用</b> {@link AssessmentRepository#findByReportId}
 *       （该仓唯一暴露 {@code report_payload::text} 的既有方法），<b>不修改</b>共享读路径。
 *       <b>注意</b>：冻结规格 §4.1 第 4 步写作 {@code findById(taskId)} 取
 *       {@code ViewRow.reportPayload()}，但当前 {@link AssessmentRepository.ViewRow} <b>不含</b>
 *       {@code reportPayload} 字段（{@code findById} 也不查询 {@code report_payload}），而规格同时
 *       禁止修改 {@link AssessmentRepository}。两者冲突时以"不得改共享读路径"为准，改用既有的
 *       {@code findByReportId(reportId)} → {@code ReportRow.reportPayload()}（规格同句给出的行号
 *       {@code AssessmentRepository:84,91} 正指向该方法）。此为第二次查询，为不改共享读路径而接受；</li>
 *   <li>payload 为空/空白 → 404 {@code RESOURCE_NOT_VISIBLE}；</li>
 *   <li>校验三项结构（{@link ReportNarrationScoreExtractor}）：缺/非法 → 422
 *       {@code UNSUPPORTED_CONTRACT}（fail-closed，绝不用 {@code metrics} 伪映射、绝不回退 mock、
 *       绝不发空 body）；</li>
 *   <li>开下游：预流失败 → 503 {@code DEPENDENCY_UNAVAILABLE} / 504 {@code DEPENDENCY_TIMEOUT}。</li>
 * </ol>
 *
 * <p><b>流内</b>（HTTP 已 200）：{@code MALFORMED}/{@code UNAVAILABLE} →
 * {@code DEPENDENCY_UNAVAILABLE}；{@code TIMEOUT} → {@code DEPENDENCY_TIMEOUT}；下游
 * {@code response.failed} 的 code 含 {@code TIMEOUT} → {@code DEPENDENCY_TIMEOUT}，否则
 * {@code DEPENDENCY_UNAVAILABLE}。循环正常结束却无终态 → 防御性写一个 {@code error}；
 * 意外 {@code RuntimeException} → 尽力写一个 {@code error}（写失败则忽略）。客户端断开
 * （写/flush {@code IOException}）→ <b>不写</b> error 终态，直接上抛，由控制器 finally 关闭下游。</p>
 *
 * <p><b>幂等语义</b>：每次调用生成全新的下游 {@code Idempotency-Key}，重试即新评估；
 * 无本地幂等存储、不支持重放。</p>
 *
 * <p>与 {@code gimbalai} 的 {@code GimbalAiService} 同源范式、刻意不共享。</p>
 */
@Service
public class ReportNarrationService {

    private static final Logger log = LoggerFactory.getLogger(ReportNarrationService.class);

    /** 预流依赖失败的固定安全文案（不泄露下游诊断）。 */
    static final String DEPENDENCY_MESSAGE = "report narration dependency failure; no narration available";

    private final AssessmentReadService readService;
    private final AssessmentRepository assessmentRepository;
    private final ReportNarrationClient client;
    private final ObjectMapper objectMapper;

    public ReportNarrationService(AssessmentReadService readService,
                                  AssessmentRepository assessmentRepository,
                                  ReportNarrationClient client,
                                  ObjectMapper objectMapper) {
        this.readService = readService;
        this.assessmentRepository = assessmentRepository;
        this.client = client;
        this.objectMapper = objectMapper;
    }

    /** 一次播报会话：下游流句柄 + 外部帧所需的固定元数据。 */
    public record Session(ReportNarrationStream stream, String requestId, String taskId, String reportId)
            implements AutoCloseable {

        @Override
        public void close() {
            stream.close();
        }
    }

    /**
     * 鉴权 + 读 payload + 校验 + 打开下游流。预流失败会抛异常（由 advice 映射为 JSON problem）。
     */
    public Session openStream(PrincipalContext principal, UUID taskId) {
        if (principal.principalType() != PrincipalType.GIMBAL) {
            throw new ApiException(ErrorCode.CALLER_NOT_ALLOWED,
                    "only a gimbal may stream the skin report narration");
        }
        AssessmentTaskView view = readService.getTask(taskId, principal);
        if (view.reportId() == null) {
            throw notReady();
        }
        String reportId = view.reportId();
        String payload = assessmentRepository.findByReportId(UUID.fromString(reportId))
                .map(AssessmentRepository.ReportRow::reportPayload)
                .orElse(null);
        if (payload == null || payload.isBlank()) {
            throw notReady();
        }

        ReportNarrationScores scores;
        try {
            scores = ReportNarrationScoreExtractor.extract(payload);
        } catch (ApiException invalid) {
            if (invalid.getCode() == ErrorCode.UNSUPPORTED_CONTRACT) {
                // 只记 taskId、失败类别与键路径清单；绝不含 payload 内容、评分值、成员资料、密钥。
                log.warn("report narration payload rejected taskId={} details={}",
                        taskId, invalid.getDetails());
            }
            throw invalid;
        }

        ReportNarrationStream downstream;
        try {
            downstream = client.openStream(scores);
        } catch (ReportNarrationException failure) {
            // 预流失败：建立 SSE 之前发生 → 统一 JSON problem（HTTP 映射），不是流内 error 事件。
            ErrorCode code = failure.kind() == ReportNarrationFailureKind.TIMEOUT
                    ? ErrorCode.DEPENDENCY_TIMEOUT
                    : ErrorCode.DEPENDENCY_UNAVAILABLE;
            log.warn("report narration pre-stream failure taskId={} kind={} downstreamStatus={} downstreamCode={}",
                    taskId, failure.kind(), failure.httpStatus(),
                    failure.safeCode() == null ? "<none>" : failure.safeCode());
            throw new ApiException(code, DEPENDENCY_MESSAGE);
        }
        return new Session(downstream, principal.requestId(), taskId.toString(), reportId);
    }

    /**
     * 消费下游事件并逐事件重编码为外部 SSE 写到 {@code out}。
     *
     * <p>外部事件序列：{@code start}（seq 1）→ {@code text_delta}×N（seq 逐个 +1）→
     * {@code done}（成功终态）；失败则以恰一个 {@code error} 终态替代。每事件即时 flush，
     * 绝不缓冲整段文案。客户端断开（写 IOException）时不写 error 终态，直接上抛。</p>
     */
    public void pump(Session session, OutputStream out) throws IOException {
        int seq = 1;
        try {
            ReportNarrationEvent event;
            while ((event = session.stream().next()) != null) {
                switch (event.type()) {
                    case ACCEPTED -> writeEvent(out, "start", json(payload(session, seq, null)));
                    case DELTA -> {
                        seq++;
                        writeEvent(out, "text_delta", json(payload(session, seq, event.delta())));
                    }
                    case COMPLETED -> {
                        seq++;
                        writeEvent(out, "done", json(payload(session, seq, null)));
                        return;
                    }
                    case FAILED -> {
                        seq++;
                        writeError(out, session, seq, codeForFailedEvent(event.failedCode()));
                        return;
                    }
                }
            }
            // 解析器保证终态；防御性兜底：仍按失败终态处理（绝不静默成功）。
            seq++;
            writeError(out, session, seq, ErrorCode.DEPENDENCY_UNAVAILABLE);
        } catch (ReportNarrationException failure) {
            ErrorCode code = failure.kind() == ReportNarrationFailureKind.TIMEOUT
                    ? ErrorCode.DEPENDENCY_TIMEOUT
                    : ErrorCode.DEPENDENCY_UNAVAILABLE;
            // 只记 taskId/分类/状态/下游码；绝不记评分值、区域值、spoken_text 或 SSE 原文。
            log.warn("report narration stream failure taskId={} kind={} downstreamStatus={} downstreamCode={}",
                    session.taskId(), failure.kind(), failure.httpStatus(),
                    failure.safeCode() == null ? "<none>" : failure.safeCode());
            seq++;
            writeError(out, session, seq, code);
        } catch (RuntimeException unexpected) {
            // 意外失败：尽力写一个 error 终态；写失败则忽略（绝不泄漏异常细节）。
            log.warn("report narration unexpected stream failure taskId={} exception={}",
                    session.taskId(), unexpected.getClass().getSimpleName());
            try {
                seq++;
                writeError(out, session, seq, ErrorCode.INTERNAL);
            } catch (IOException ignored) {
                // 客户端已断开或写入失败：无更多可做。
            }
        }
    }

    private static ErrorCode codeForFailedEvent(String downstreamCode) {
        if (downstreamCode != null && downstreamCode.toUpperCase().contains("TIMEOUT")) {
            return ErrorCode.DEPENDENCY_TIMEOUT;
        }
        return ErrorCode.DEPENDENCY_UNAVAILABLE;
    }

    private void writeError(OutputStream out, Session session, int seq, ErrorCode code) throws IOException {
        Map<String, Object> data = payload(session, seq, null);
        data.put("code", code.name());
        data.put("message", ReportNarrationStreamController.ERROR_MESSAGE);
        writeEvent(out, "error", json(data));
    }

    /** start/text_delta/done 的 data 载荷（键序 requestId、taskId、reportId、seq[、delta]）。 */
    private static Map<String, Object> payload(Session session, int seq, String delta) {
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("requestId", session.requestId());
        data.put("taskId", session.taskId());
        data.put("reportId", session.reportId());
        data.put("seq", seq);
        if (delta != null) {
            data.put("delta", delta);
        }
        return data;
    }

    private void writeEvent(OutputStream out, String event, String jsonData) throws IOException {
        out.write(("event: " + event + "\ndata: " + jsonData + "\n\n")
                .getBytes(StandardCharsets.UTF_8));
        out.flush();
    }

    private String json(Object value) {
        try {
            return objectMapper.writeValueAsString(value);
        } catch (Exception encoding) {
            throw new IllegalStateException("failed to encode SSE event payload");
        }
    }

    private static ApiException notReady() {
        return new ApiException(ErrorCode.RESOURCE_NOT_VISIBLE,
                "report not ready; narration is not available");
    }
}

package cn.yuanxin.mvp.web.assessments.narration;

import cn.yuanxin.mvp.web.auth.PrincipalContext;
import cn.yuanxin.mvp.web.error.ApiException;
import org.springframework.http.CacheControl;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.servlet.mvc.method.annotation.StreamingResponseBody;

import java.util.UUID;

/**
 * 测肤报告播报 SSE 端点（真实转发下游报告评估 SSE）。
 *
 * <p>{@code GET /api/v1/skin-assessment-tasks/{taskId}/report-narration-stream}：
 * Bearer 认证 → 仅云台主体（APP → 403 CALLER_NOT_ALLOWED）。预流检查与下游开流在请求线程按序
 * 完成（{@link ReportNarrationService#openStream}）：主体校验、既有任务可见性
 * （{@link cn.yuanxin.mvp.web.assessments.AssessmentReadService#getTask} 内部产出 404/409）、
 * 报告就绪（reportId 为空 → 404）、T05 {@code report_payload} 三项结构校验
 * （缺/非法 → 422 UNSUPPORTED_CONTRACT）、下游预流失败（503/504）。任一失败在返回 SSE 之前
 * 抛 {@link ApiException}，由 {@link ReportNarrationStreamErrorAdvice} 映射为真实 HTTP 状态的
 * JSON 错误信封（即使客户端带 {@code Accept: text/event-stream}）。</p>
 *
 * <p>预流成功后才建立 {@code text/event-stream}（{@code Cache-Control: no-store}），逐事件
 * 即时 flush：{@code start → text_delta ×N → done}，{@code seq} 从 1 起严格 +1；流内失败以
 * 恰好一个 {@code error} 终态表达（HTTP 仍 200）。客户端断开（写/flush IOException）时
 * {@code finally} 关闭下游 AI 连接。不支持 Last-Event-ID、断点续传、重放或取消 API。</p>
 */
@RestController
@Validated
public class ReportNarrationStreamController {

    /** 流内失败终态的固定安全文案（绝不携带异常细节/堆栈）。 */
    static final String ERROR_MESSAGE = "报告播报生成失败";

    private final ReportNarrationService service;

    public ReportNarrationStreamController(ReportNarrationService service) {
        this.service = service;
    }

    @GetMapping(value = "/api/v1/skin-assessment-tasks/{taskId}/report-narration-stream",
            produces = MediaType.TEXT_EVENT_STREAM_VALUE)
    public ResponseEntity<StreamingResponseBody> reportNarrationStream(
            @PathVariable UUID taskId,
            PrincipalContext principal) {
        // 预流检查 + 开下游（请求线程，任一失败 → 统一 JSON 错误信封，绝不进入 SSE）。
        ReportNarrationService.Session session = service.openStream(principal, taskId);
        StreamingResponseBody stream = output -> {
            try {
                service.pump(session, output);
            } finally {
                // 正常完成或客户端断开：始终取消/关闭下游 AI 连接。
                session.close();
            }
        };
        return ResponseEntity.ok()
                .contentType(MediaType.TEXT_EVENT_STREAM)
                .cacheControl(CacheControl.noStore())
                .body(stream);
    }
}

