package cn.yuanxin.mvp.web.docs.catalog;

import cn.yuanxin.mvp.web.config.NonProductionCondition;
import cn.yuanxin.mvp.web.error.ErrorCode;
import io.swagger.v3.oas.models.tags.Tag;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.Conditional;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.Map;

/**
 * 测肤报告文案播报域联调文档目录：
 * {@code GET /api/v1/skin-assessment-tasks/{taskId}/report-narration-stream}（响应为 SSE）。
 *
 * <p>本端点是<b>用户授权的增量</b>：从 T05 {@code report_payload} 读取三项评分并真实转发给
 * 已部署的 llm-rag-api 报告评估 SSE（{@code POST
 * /internal/v1/weijing/reports/assess:stream}）。它<b>不在</b>
 * {@code backend/contracts/openapi/openapi.yaml} 的既有操作集中，故 <b>catalog-only</b>：
 * 仅登记于本目录，不写入契约（也正因此，覆盖率门禁对该无契约操作跳过错误码集交叉校验）。</p>
 *
 * <p><b>限制声明（必须如实展示）</b>：当前 Worker 写入的 {@code report_payload} 只有
 * {@code schema_version}/{@code conclusion}/{@code metrics}/{@code description}/{@code images}/
 * {@code model_info} 六个键，<b>不含</b> {@code pores}/{@code spots}/{@code surface_gloss}
 * ⇒ 真实报告会在发 AI 前以 422 {@code UNSUPPORTED_CONTRACT} fail-closed，端到端尚未打通；
 * 另有两处口径（{@code score=null} 的可接受性、regions 左右/区域码是否需要转换）待真实 AI 实测确认。</p>
 *
 * <p>本类只写文档内容，不触碰任何控制器/DTO/业务代码。</p>
 */
@Component
@Conditional(NonProductionCondition.class)
@ConditionalOnProperty(name = "springdoc.api-docs.enabled", havingValue = "true")
public class ReportNarrationStreamDocs implements ApiDocsCatalog {

    /** 测肤报告播报。 */
    private static final String TAG_REPORT_NARRATION = "测肤报告播报";

    @Override
    public String domain() {
        return "report-narration";
    }

    @Override
    public List<Tag> tags() {
        return List.of(new Tag().name(TAG_REPORT_NARRATION)
                .description("测肤报告文案播报流（用户授权增量）：云台按任务触发服务端真实转发 llm-rag-api 的"
                        + "报告评估 SSE，并以 SSE 逐事件回传；不支持重放。"));
    }

    @Override
    public Map<String, ApiDocEntry> entries() {
        return Map.of(
                "GET /api/v1/skin-assessment-tasks/{taskId}/report-narration-stream",
                new ApiDocEntry(
                        TAG_REPORT_NARRATION,
                        "测肤报告文案播报流（SSE）",
                        """
                        用途：云台在报告就绪后按任务触发服务端读取 T05 持久化的三项评分，真实转发给
                        llm-rag-api 的报告评估 SSE，并以 SSE 逐事件回传播报文案（仅 delta，不转发 AI 完整事件）。
                        调用方主体：仅云台设备会话（Authorization: Bearer <gimbal device session token>）；
                        APP 会话主体一律 403 CALLER_NOT_ALLOWED 且不产生任何下游请求；未认证请求由
                        BearerAuthFilter 统一 401（AUTH_REQUIRED/SESSION_INVALID）。
                        前置与顺序（预流检查在请求线程按序完成，任一失败在建立 SSE 前返回统一 JSON 错误信封）：
                        ① 仅云台主体；② taskId 必须对该云台可见（非本云台任务 → 404 RESOURCE_NOT_VISIBLE；
                        已非该云台当前任务 → 409 TASK_REPLACED）；③ 任务报告必须已就绪（reportId 非空），否则
                        404 RESOURCE_NOT_VISIBLE；④ T05 report_payload 必须含 pores/spots/surface_gloss 三个
                        JSON 对象且各组通过评分结构校验，否则 422 UNSUPPORTED_CONTRACT（fail-closed，绝不回退
                        替身/合成文案、绝不把 metrics 伪映射成三项）；⑤ 下游连接失败/预流非 2xx → 503
                        DEPENDENCY_UNAVAILABLE，预流超时 → 504 DEPENDENCY_TIMEOUT。
                        成功响应：200，Content-Type: text/event-stream、Cache-Control: no-store。
                        事件映射与 seq 纪律：下游 response.accepted → start、response.delta → text_delta、
                        response.completed → done、response.failed → error；服务端逐事件即时 flush（绝不缓冲整段
                        文案），seq 从 1 起每事件严格 +1（start=1，其后每个 text_delta 与唯一终态逐个 +1）。
                        data 为 JSON，含 requestId/taskId/reportId/seq；text_delta 另含 delta；done 只带安全元数据
                        （不带完整 spoken_text/plan/指标/任何评估结果）；error 含 code 与固定安全 message。
                        成功流恰一个终态；零 delta 却收到 completed 视为失败（error 终态），累计 delta 与
                        completed.spoken_text 不一致只记服务端告警、仍正常发 done。
                        下游契约（服务端内部）：POST {app.report-narration.base-url}/internal/v1/weijing/reports/
                        assess:stream，Header X-Service-Name=medical-platform、X-API-Key、X-Request-Id（每次调用
                        新生成）、Idempotency-Key（每次调用全新，不发送 Last-Event-ID、绝不断点续传）、
                        X-Protocol-Version=1.0、traceparent（W3C）、Accept: text/event-stream、
                        Content-Type: application/json；body 恰好 {"pores":{...},"spots":{...},
                        "surface_gloss":{...}}，每组只含白名单四键 score/severity/name/regions，不发送图片、
                        成员资料、完整 report_payload、metrics 或其它 trace；绝不转发云台的 Authorization/Cookie。
                        幂等语义（重要限制）：本端点无本地幂等存储，每次调用都使用全新的下游 Idempotency-Key
                        ——客户端重试会产生一次新评估（下游亦无重放存储），不支持重放。
                        配置与降级：app.report-narration.base-url / api-key 缺省为空（安全占位），真实值由部署
                        环境注入；app.providers.mode=disabled 或未配置（非生产）时一律预流 503
                        DEPENDENCY_UNAVAILABLE，绝不回退替身或合成文案；生产信号下缺配置拒绝启动。
                        错误处理：CALLER_NOT_ALLOWED 换用云台会话；RESOURCE_NOT_VISIBLE 换任务或等待报告就绪；
                        TASK_REPLACED 以当前任务为准；UNSUPPORTED_CONTRACT（422）表示持久化载荷不符合三项评分
                        契约（当前 Worker 报告即属此类，端到端尚未打通），非重试类；DEPENDENCY_UNAVAILABLE（503）
                        与 DEPENDENCY_TIMEOUT（504）为下游依赖失败/超时（预流为 HTTP 问题，流内为 error 事件），
                        受限重试（注意"重试即新评估"语义）。
                        限制声明（必须如实展示）：不支持 Last-Event-ID、断点续传、重放或取消 API；客户端断开时
                        服务端取消下游 AI 连接。当前 Worker 的 report_payload 不含三项评分，真实报告会在发 AI 前
                        422 fail-closed，端到端尚未打通；score=null 的可接受性与 regions 左右/区域码口径两处
                        待真实 AI 实测确认，本实现不做任何语义转换。本接口为 catalog-only（按用户授权增量，
                        不入 backend/contracts/openapi/openapi.yaml）。
                        """,
                        List.of(new ApiDocEntry.ParamDoc("taskId", "path",
                                "必填，path，UUID 字符串（T05.id），测肤任务引用；必须仍是该云台的当前任务"
                                        + "且报告已就绪，其持久化 report_payload 须含三项评分对象。",
                                "7f3c2b1a-9d4e-4c5f-8a6b-1d2e3f4a5b6c", null)),
                        List.of(),
                        null,
                        null,
                        List.of(ApiDocEntry.SuccessDoc.binary("200",
                                "SSE 事件流（Content-Type: text/event-stream、Cache-Control: no-store）。"
                                        + "事件序列 start → text_delta ×N → done（或恰一个 error 终态），"
                                        + "每事件即时 flush；data 含 requestId/taskId/reportId/seq"
                                        + "（text_delta 另含 delta）；预流失败改以 JSON 错误信封表达",
                                "text/event-stream")),
                        List.of(ErrorCode.AUTH_REQUIRED, ErrorCode.SESSION_INVALID,
                                ErrorCode.CALLER_NOT_ALLOWED, ErrorCode.RESOURCE_NOT_VISIBLE,
                                ErrorCode.TASK_REPLACED, ErrorCode.UNSUPPORTED_CONTRACT,
                                ErrorCode.DEPENDENCY_UNAVAILABLE, ErrorCode.DEPENDENCY_TIMEOUT)));
    }

    @Override
    public Map<String, Map<String, PropertyDoc>> propertyDocs() {
        return Map.of();
    }

    @Override
    public Map<String, FreeFormDoc> freeFormDocs() {
        return Map.of();
    }
}

package cn.yuanxin.mvp.web.assessments.narration;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;

import java.io.IOException;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * 报告评估 AI 服务 {@code POST /internal/v1/weijing/reports/assess:stream} 的本地 HTTP stub
 * （随机端口）。记录方法/路径/首值 header/原始 body；支持脚本化分帧 SSE、静默保持、
 * 慢/巨 problem body、静默打点（检测客户端断开）。
 *
 * <p>本 stub 与 {@code gimbalai/AiResponseStub} 同源思路但<b>各自独立</b>，未修改对方；
 * 事件名与 completed 字段（{@code spoken_text}）按报告评估契约。测试用，不访问真实服务；
 * 使用的 key 一律是明显假值。</p>
 */
final class ReportNarrationAiStub implements AutoCloseable {

    static final String FAKE_API_KEY = "FAKE-NARRATION-KEY-DO-NOT-USE";

    private static final ObjectMapper JSON = new ObjectMapper();

    record Captured(String method, String path, Map<String, String> headers, String body) {
        String header(String name) {
            return headers.get(name.toLowerCase(Locale.ROOT));
        }
    }

    static String accepted() {
        return frame("response.accepted", "{\"request_id\":\"stub-accepted\"}");
    }

    static String delta(String text) {
        return frame("response.delta", "{\"delta\":" + quote(text) + "}");
    }

    static String completed(String spokenText) {
        return frame("response.completed", "{\"spoken_text\":" + quote(spokenText) + "}");
    }

    static String failed(String code) {
        return frame("response.failed", "{\"code\":" + quote(code) + "}");
    }

    /** 便捷合法流：accepted + 两个 delta + completed。 */
    static String sse(String spokenText) {
        String first = spokenText.length() > 1 ? spokenText.substring(0, 1) : spokenText;
        String second = spokenText.length() > 1 ? spokenText.substring(1) : "";
        return accepted() + delta(first) + delta(second) + completed(spokenText);
    }

    private static String frame(String event, String json) {
        return "event: " + event + "\ndata: " + json + "\n\n";
    }

    private static String quote(String value) {
        try {
            return JSON.writeValueAsString(value);
        } catch (Exception impossible) {
            throw new IllegalStateException(impossible);
        }
    }

    private final List<Captured> requests = new CopyOnWriteArrayList<>();
    private final AtomicBoolean clientDisconnected = new AtomicBoolean();

    private volatile int status = 200;
    private volatile String body = sse("stub narration");
    private volatile List<String> scriptFrames = null;
    private volatile long holdBeforeFirstFrameMillis = 0;
    private volatile long holdBeforeHeadersMillis = 0;
    private volatile long holdOpenSilentlyMillis = 0;
    private volatile String slowProblemPrefix = null;
    private volatile long slowProblemHoldMillis = 0;

    private HttpServer server;

    void start() throws IOException {
        server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        server.createContext("/", this::handle);
        server.start();
    }

    String baseUrl() {
        return "http://127.0.0.1:" + server.getAddress().getPort();
    }

    /** 固定状态/整段 body（用于错误与非流场景）。 */
    void respond(int responseStatus, String responseBody) {
        clearModes();
        this.status = responseStatus;
        this.body = responseBody;
    }

    /** 分帧流：逐帧 flush。 */
    void script(List<String> frames) {
        clearModes();
        this.scriptFrames = List.copyOf(frames);
        this.status = 200;
    }

    /** 连响应头都保持静默（触发客户端预流超时；随后写 body 以观测客户端是否已断开）。 */
    void holdHeadersSilently(long millis) {
        clearModes();
        this.holdBeforeHeadersMillis = millis;
        this.status = 200;
    }

    /** 发响应头后、首帧前保持连接静默（触发客户端读取超时）。 */
    void holdConnectionSilently(long millis) {
        clearModes();
        this.holdBeforeFirstFrameMillis = millis;
        this.scriptFrames = List.of();
        this.status = 200;
    }

    /**
     * 发完 frames 后"永不发送终态"：每 {@code probeMillis} 静默写入一个单字节 {@code ':'} 并 flush；
     * 一旦客户端断开，写入抛 IOException，stub 记录 {@link #clientDisconnected}。
     */
    void holdOpenSilently(List<String> preFrames, long probeMillis) {
        clearModes();
        this.scriptFrames = List.copyOf(preFrames);
        this.holdOpenSilentlyMillis = Math.max(1, probeMillis);
        this.status = 200;
    }

    /** 非 2xx 慢 problem body：chunked 发送 prefix 后保持 holdMillis（触发读取期限）。 */
    void slowProblemBody(int responseStatus, String prefix, long holdMillis) {
        clearModes();
        this.status = responseStatus;
        this.slowProblemPrefix = prefix;
        this.slowProblemHoldMillis = holdMillis;
    }

    boolean clientDisconnected() {
        return clientDisconnected.get();
    }

    boolean awaitClientDisconnected(long timeoutMillis) {
        long deadline = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(timeoutMillis);
        while (System.nanoTime() < deadline) {
            if (clientDisconnected.get()) {
                return true;
            }
            sleep(25);
        }
        return clientDisconnected.get();
    }

    List<Captured> requests() {
        return requests;
    }

    Captured lastRequest() {
        return requests.isEmpty() ? null : requests.get(requests.size() - 1);
    }

    void reset() {
        clearModes();
        this.status = 200;
        this.body = sse("stub narration");
        this.requests.clear();
        this.clientDisconnected.set(false);
    }

    private void clearModes() {
        this.scriptFrames = null;
        this.holdBeforeFirstFrameMillis = 0;
        this.holdBeforeHeadersMillis = 0;
        this.holdOpenSilentlyMillis = 0;
        this.slowProblemPrefix = null;
        this.slowProblemHoldMillis = 0;
    }

    private void handle(HttpExchange exchange) throws IOException {
        byte[] raw = exchange.getRequestBody().readAllBytes();
        Map<String, String> headers = new LinkedHashMap<>();
        exchange.getRequestHeaders().forEach((name, values) ->
                headers.put(name.toLowerCase(Locale.ROOT), values.isEmpty() ? null : values.get(0)));
        requests.add(new Captured(exchange.getRequestMethod(),
                exchange.getRequestURI().getPath(), headers,
                new String(raw, StandardCharsets.UTF_8)));

        boolean stream = exchange.getRequestURI().getPath().endsWith(":stream");
        try {
            if (stream && status >= 200 && status < 300) {
                streamResponse(exchange);
            } else {
                fixedResponse(exchange, stream);
            }
        } catch (IOException clientGone) {
            clientDisconnected.set(true);
        } finally {
            exchange.close();
        }
    }

    private void streamResponse(HttpExchange exchange) throws IOException {
        if (holdBeforeHeadersMillis > 0) {
            sleep(holdBeforeHeadersMillis);
        }
        exchange.getResponseHeaders().set("Content-Type", "text/event-stream");
        exchange.sendResponseHeaders(status, 0); // chunked
        OutputStream out = exchange.getResponseBody();
        if (holdBeforeFirstFrameMillis > 0) {
            sleep(holdBeforeFirstFrameMillis);
        }
        List<String> frames = scriptFrames;
        if (frames == null) {
            out.write(body.getBytes(StandardCharsets.UTF_8));
            out.flush();
            return;
        }
        for (String frame : frames) {
            out.write(frame.getBytes(StandardCharsets.UTF_8));
            out.flush();
        }
        long probeMillis = holdOpenSilentlyMillis;
        if (probeMillis > 0) {
            long maxProbes = Math.max(1, 10_000 / probeMillis); // ~10s 上限，防测试挂死
            for (long i = 0; i < maxProbes; i++) {
                sleep(probeMillis);
                out.write(':');
                out.flush();
            }
        }
    }

    private void fixedResponse(HttpExchange exchange, boolean stream) throws IOException {
        exchange.getResponseHeaders().set("Content-Type",
                stream ? "text/event-stream" : "application/json");
        String prefix = slowProblemPrefix;
        if (prefix != null && slowProblemHoldMillis > 0) {
            exchange.sendResponseHeaders(status, 0); // chunked trickle
            OutputStream out = exchange.getResponseBody();
            out.write(prefix.getBytes(StandardCharsets.UTF_8));
            out.flush();
            sleep(slowProblemHoldMillis);
            out.write("}".getBytes(StandardCharsets.UTF_8));
            out.flush();
            return;
        }
        byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
        exchange.sendResponseHeaders(status, bytes.length);
        exchange.getResponseBody().write(bytes);
    }

    private static void sleep(long millis) {
        try {
            Thread.sleep(millis);
        } catch (InterruptedException interrupted) {
            Thread.currentThread().interrupt();
        }
    }

    @Override
    public void close() {
        if (server != null) {
            server.stop(0);
        }
    }
}

package cn.yuanxin.mvp.web.assessments.narration;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * {@link ReportNarrationSseParser} 增量解析与 fail-closed 规则单测（无网络）：
 * 只认四事件、恰一个终态、终态后事件/重复终态/缺终态/畸形/空流一律 MALFORMED；
 * 并锁定 §6.3 两条流纪律（零 delta + completed 失败；拼接不一致仍 completed）。
 */
class ReportNarrationSseParserTest {

    /** 内存行源：按行喂入；null 表示 EOF。 */
    private static final class ListLineSource implements ReportNarrationLineSource {
        private final Deque<String> lines = new ArrayDeque<>();
        private boolean closed;

        ListLineSource(String... lines) {
            java.util.Arrays.stream(lines).forEach(this.lines::add);
        }

        @Override
        public String readLine() {
            return lines.isEmpty() ? null : lines.poll();
        }

        @Override
        public void close() {
            closed = true;
        }
    }

    private static List<ReportNarrationEvent> drain(ReportNarrationSseParser parser) {
        List<ReportNarrationEvent> events = new ArrayList<>();
        ReportNarrationEvent event;
        while ((event = parser.next()) != null) {
            events.add(event);
        }
        return events;
    }

    private static ReportNarrationSseParser parser(String body) {
        String[] lines = body.split("\r\n|\n|\r", -1);
        return new ReportNarrationSseParser(new ListLineSource(lines));
    }

    @Test
    @DisplayName("accepted + delta×2 + completed：按序累加，completed.spoken_text 权威")
    void acceptedDeltasCompleted() {
        ReportNarrationSseParser parser = parser(
                "event: response.accepted\ndata: {\"request_id\":\"r\"}\n\n"
                        + "event: response.delta\ndata: {\"delta\":\"Hello \"}\n\n"
                        + "event: response.delta\ndata: {\"delta\":\"world\"}\n\n"
                        + "event: response.completed\ndata: {\"spoken_text\":\"Hello world\"}\n\n");

        List<ReportNarrationEvent> events = drain(parser);
        assertThat(events).extracting(ReportNarrationEvent::type).containsExactly(
                ReportNarrationEvent.Type.ACCEPTED, ReportNarrationEvent.Type.DELTA,
                ReportNarrationEvent.Type.DELTA, ReportNarrationEvent.Type.COMPLETED);
        assertThat(events.get(1).delta()).isEqualTo("Hello ");
        assertThat(events.get(2).delta()).isEqualTo("world");
        assertThat(events.get(3).spokenText()).isEqualTo("Hello world");
    }

    @Test
    @DisplayName("§6.3 零 delta + completed → MALFORMED（绝不假成功 done）")
    void completedWithoutAnyDeltaRejected() {
        for (String body : List.of(
                "event: response.completed\ndata: {\"spoken_text\":\"done\"}\n\n",
                "event: response.accepted\ndata: {}\n\n"
                        + "event: response.completed\ndata: {\"spoken_text\":\"done\"}\n\n")) {
            ReportNarrationSseParser parser = parser(body);
            assertThatThrownBy(() -> drain(parser))
                    .as("body=%s", body)
                    .isInstanceOf(ReportNarrationException.class)
                    .satisfies(thrown -> assertThat(((ReportNarrationException) thrown).kind())
                            .isEqualTo(ReportNarrationFailureKind.MALFORMED));
        }
    }

    @Test
    @DisplayName("§6.3 累计 delta 与 spoken_text 不一致 → 仍 COMPLETED（只告警不失败）")
    void mismatchStillCompletes() {
        List<ReportNarrationEvent> events = drain(parser(
                "event: response.delta\ndata: {\"delta\":\"Hello world\"}\n\n"
                        + "event: response.completed\ndata: {\"spoken_text\":\"Hello world!\"}\n\n"));
        assertThat(events).extracting(ReportNarrationEvent::type)
                .containsExactly(ReportNarrationEvent.Type.DELTA, ReportNarrationEvent.Type.COMPLETED);
        assertThat(events.get(1).spokenText()).isEqualTo("Hello world!");
    }

    @Test
    @DisplayName("failed 终态 → FAILED 事件（携带下游 code，供安全映射）")
    void failedTerminal() {
        List<ReportNarrationEvent> events = drain(parser(
                "event: response.delta\ndata: {\"delta\":\"partial\"}\n\n"
                        + "event: response.failed\ndata: {\"code\":\"AI_UPSTREAM_TIMEOUT\",\"retryable\":true}\n\n"));
        assertThat(events).extracting(ReportNarrationEvent::type).containsExactly(
                ReportNarrationEvent.Type.DELTA, ReportNarrationEvent.Type.FAILED);
        assertThat(events.get(1).failedCode()).isEqualTo("AI_UPSTREAM_TIMEOUT");
    }

    @Test
    @DisplayName("多行 data / CRLF / 注释（heartbeat）/ id|retry 字段：按规范解析")
    void sseSyntaxVariants() {
        ReportNarrationSseParser parser = parser(
                ": keep-alive comment\r\n"
                        + "id: 42\r\n"
                        + "event: response.delta\r\n"
                        + "data: {\"delta\":\r\n"
                        + "data: \"multi\"}\r\n"
                        + "\r\n"
                        + "retry: 1000\r\n"
                        + "event: response.completed\r\n"
                        + "data: {\"spoken_text\":\"multi\"}\r\n\r\n");
        List<ReportNarrationEvent> events = drain(parser);
        assertThat(events).extracting(ReportNarrationEvent::type).containsExactly(
                ReportNarrationEvent.Type.DELTA, ReportNarrationEvent.Type.COMPLETED);
        assertThat(events.get(0).delta()).isEqualTo("multi");
        assertThat(events.get(1).spokenText()).isEqualTo("multi");
    }

    @Test
    @DisplayName("未知事件 → MALFORMED")
    void unknownEventRejected() {
        ReportNarrationSseParser parser = parser("event: something-else\ndata: {}\n\n");
        assertThatThrownBy(() -> parser.next())
                .isInstanceOf(ReportNarrationException.class)
                .satisfies(thrown -> assertThat(((ReportNarrationException) thrown).kind())
                        .isEqualTo(ReportNarrationFailureKind.MALFORMED));
    }

    @Test
    @DisplayName("重复终态 / 终态后事件 → MALFORMED")
    void duplicateOrPostTerminalRejected() {
        for (String body : List.of(
                "event: response.delta\ndata: {\"delta\":\"a\"}\n\n"
                        + "event: response.completed\ndata: {\"spoken_text\":\"a\"}\n\n"
                        + "event: response.completed\ndata: {\"spoken_text\":\"a\"}\n\n",
                "event: response.delta\ndata: {\"delta\":\"a\"}\n\n"
                        + "event: response.completed\ndata: {\"spoken_text\":\"a\"}\n\n"
                        + "event: response.delta\ndata: {\"delta\":\"late\"}\n\n",
                "event: response.failed\ndata: {\"code\":\"x\"}\n\n"
                        + "event: response.completed\ndata: {\"spoken_text\":\"a\"}\n\n")) {
            ReportNarrationSseParser parser = parser(body);
            assertThatThrownBy(() -> drain(parser))
                    .as("body=%s", body)
                    .isInstanceOf(ReportNarrationException.class)
                    .satisfies(thrown -> assertThat(((ReportNarrationException) thrown).kind())
                            .isEqualTo(ReportNarrationFailureKind.MALFORMED));
        }
    }

    @Test
    @DisplayName("缺终态（deltas 后 EOF）/ 空流 → MALFORMED")
    void missingTerminalRejected() {
        for (String body : List.of(
                "",
                "event: response.delta\ndata: {\"delta\":\"only\"}\n\n",
                "event: response.accepted\ndata: {}\n\n")) {
            ReportNarrationSseParser parser = parser(body);
            assertThatThrownBy(() -> drain(parser))
                    .as("body=%s", body)
                    .isInstanceOf(ReportNarrationException.class)
                    .satisfies(thrown -> assertThat(((ReportNarrationException) thrown).kind())
                            .isEqualTo(ReportNarrationFailureKind.MALFORMED));
        }
    }

    @Test
    @DisplayName("畸形数据（非 JSON / 非对象 / delta 缺文本 / completed 缺非空 spoken_text / data 无 event）→ MALFORMED")
    void malformedPayloadsRejected() {
        for (String body : List.of(
                "event: response.delta\ndata: not-json\n\n",
                "event: response.delta\ndata: []\n\n",
                "event: response.delta\ndata: {\"nope\":\"x\"}\n\n",
                "event: response.completed\ndata: {\"spoken_text\":\"\"}\n\n",
                "event: response.completed\ndata: {\"spoken_text\":\"   \"}\n\n",
                "event: response.completed\ndata: {\"answer\":{\"text\":\"x\"}}\n\n",
                "data: {\"delta\":\"x\"}\n\n")) {
            ReportNarrationSseParser parser = parser(body);
            assertThatThrownBy(() -> drain(parser))
                    .as("body=%s", body)
                    .isInstanceOf(ReportNarrationException.class)
                    .satisfies(thrown -> assertThat(((ReportNarrationException) thrown).kind())
                            .isEqualTo(ReportNarrationFailureKind.MALFORMED));
        }
    }

    @Test
    @DisplayName("close() 委托底层行源（取消下游）")
    void closeDelegates() {
        ListLineSource source = new ListLineSource(
                "event: response.delta\ndata: {\"delta\":\"a\"}\n\n",
                "event: response.completed\ndata: {\"spoken_text\":\"a\"}\n");
        ReportNarrationSseParser parser = new ReportNarrationSseParser(source);
        parser.close();
        assertThat(source.closed).isTrue();
    }

    @Test
    @DisplayName("单事件 data 超上限 → MALFORMED（有界，不无界累积）")
    void oversizedEventDataRejected() {
        ReportNarrationSseParser parser = parser(
                "data: " + "x".repeat(ReportNarrationSseParser.MAX_EVENT_DATA_CHARS + 1) + "\n\n");
        assertThatThrownBy(() -> parser.next())
                .isInstanceOf(ReportNarrationException.class)
                .satisfies(thrown -> assertThat(((ReportNarrationException) thrown).kind())
                        .isEqualTo(ReportNarrationFailureKind.MALFORMED));
    }

    @Test
    @DisplayName("completed.spoken_text 超上限 → MALFORMED")
    void oversizedCompletedSpokenTextRejected() {
        String text = "y".repeat(ReportNarrationSseParser.MAX_ACCUMULATED_CHARS + 1);
        ReportNarrationSseParser parser = parser(
                "event: response.delta\ndata: {\"delta\":\"a\"}\n\n"
                        + "event: response.completed\ndata: {\"spoken_text\":\"" + text + "\"}\n\n");
        assertThatThrownBy(() -> parser.next())
                .isInstanceOf(ReportNarrationException.class)
                .satisfies(thrown -> assertThat(((ReportNarrationException) thrown).kind())
                        .isEqualTo(ReportNarrationFailureKind.MALFORMED));
    }

    @Test
    @DisplayName("response.failed.code 归一：合法码保留，非法（小写/超长/空格）→ null")
    void failedCodeSanitized() {
        List<ReportNarrationEvent> valid = drain(parser(
                "event: response.delta\ndata: {\"delta\":\"a\"}\n\n"
                        + "event: response.failed\ndata: {\"code\":\"AI_UPSTREAM_TIMEOUT\"}\n\n"));
        assertThat(valid.get(1).failedCode()).isEqualTo("AI_UPSTREAM_TIMEOUT");

        for (String malicious : List.of(
                "lower_case",
                "has space and user text",
                "A".repeat(65),
                "BAD-CODE")) {
            ReportNarrationSseParser parser = parser(
                    "event: response.delta\ndata: {\"delta\":\"a\"}\n\n"
                            + "event: response.failed\ndata: {\"code\":\"" + malicious + "\"}\n\n");
            List<ReportNarrationEvent> events = drain(parser);
            assertThat(events).hasSize(2);
            assertThat(events.get(1).failedCode()).as("code=%s", malicious).isNull();
        }
    }
}

package cn.yuanxin.mvp.web.assessments.narration;

import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * {@link ReportNarrationScoreExtractor} 白名单抽取与 fail-closed 单测（无网络）：
 * 缺三项/类型非法/取值越界一律 422 UNSUPPORTED_CONTRACT，details 只含结构性键路径；
 * score/severity 的 null 原样透传；未知键丢弃；区域零转换。
 */
class ReportNarrationScoreExtractorTest {

    private static final String FULL = """
            {
              "schema_version": 1,
              "conclusion": "ignored",
              "metrics": [{"name":"moisture","value":50,"unit":"%"}],
              "pores": {"score": 61, "severity": "mild", "name": "毛孔",
                        "regions": [{"region":"F","name":"额头","score":40,"severity":"ok"}]},
              "spots": {"score": null, "severity": null, "name": "斑点",
                        "regions": [{"region":"L","name":"左脸","score":null,"severity":null}]},
              "surface_gloss": {"score": 67.5, "severity": "none", "name": "光泽",
                        "regions": [{"region":"R","name":"右脸","score":82,"severity":"good"}]}
            }
            """;

    private static ApiException rejected(String payload) {
        return (ApiException) org.assertj.core.api.Assertions.catchThrowable(
                () -> ReportNarrationScoreExtractor.extract(payload));
    }

    @SuppressWarnings("unchecked")
    private static List<String> detail(ApiException failure, String key) {
        Map<String, Object> details = failure.getDetails();
        assertThat(details).isNotNull();
        return (List<String>) details.get(key);
    }

    @Test
    @DisplayName("合法三项：只取三项，score/severity null 原样保留，decimals 不丢精度")
    void extractsThreeGroups() {
        ReportNarrationScores scores = ReportNarrationScoreExtractor.extract(FULL);

        assertThat(scores.pores().name()).isEqualTo("毛孔");
        assertThat(scores.pores().score()).isEqualByComparingTo("61");
        assertThat(scores.pores().regions()).hasSize(1);
        assertThat(scores.pores().regions().get(0).region()).isEqualTo("F");

        assertThat(scores.spots().score()).isNull();
        assertThat(scores.spots().severity()).isNull();
        assertThat(scores.spots().regions().get(0).score()).isNull();

        assertThat(scores.surfaceGloss().score()).isEqualByComparingTo("67.5");
    }

    @Test
    @DisplayName("仅 metrics（当前 Worker 形状）→ 422，missing 恰为三项")
    void metricsOnlyPayloadRejected() {
        ApiException failure = rejected(
                "{\"schema_version\":1,\"conclusion\":\"x\","
                        + "\"metrics\":[{\"name\":\"moisture\",\"value\":50,\"unit\":\"%\"}]}");
        assertThat(failure.getCode()).isEqualTo(ErrorCode.UNSUPPORTED_CONTRACT);
        assertThat(detail(failure, "missing"))
                .containsExactlyInAnyOrder("pores", "spots", "surface_gloss");
    }

    @Test
    @DisplayName("缺任一顶层组 → 422，missing 精确列出")
    void missingGroupRejected() {
        ApiException failure = rejected(
                "{\"spots\":{\"name\":\"s\",\"regions\":[{\"region\":\"F\",\"name\":\"额\"}]},"
                        + "\"surface_gloss\":{\"name\":\"g\",\"regions\":[{\"region\":\"F\",\"name\":\"额\"}]}}");
        assertThat(failure.getCode()).isEqualTo(ErrorCode.UNSUPPORTED_CONTRACT);
        assertThat(detail(failure, "missing")).containsExactly("pores");
    }

    @Test
    @DisplayName("顶层组类型不符 / payload 非对象 / 非 JSON → 422 invalid")
    void typeMismatchRejected() {
        assertThat(detail(rejected("{\"pores\":[],\"spots\":{\"name\":\"s\",\"regions\":[{\"region\":\"F\",\"name\":\"额\"}]},"
                + "\"surface_gloss\":{\"name\":\"g\",\"regions\":[{\"region\":\"F\",\"name\":\"额\"}]}}"),
                "invalid")).contains("pores");
        assertThat(detail(rejected("[]"), "invalid")).contains("report_payload");
        assertThat(detail(rejected("not json"), "invalid")).contains("report_payload");
    }

    @Test
    @DisplayName("score 越界 / 非 number → 422 invalid 键路径")
    void invalidScoreRejected() {
        assertThat(detail(rejected(group("pores", "\"score\":101")), "invalid"))
                .contains("pores.score");
        assertThat(detail(rejected(group("pores", "\"score\":-1")), "invalid"))
                .contains("pores.score");
        assertThat(detail(rejected(group("pores", "\"score\":\"61\"")), "invalid"))
                .contains("pores.score");
    }

    @Test
    @DisplayName("severity 空白 / 非 string → 422 invalid；缺失视为 null")
    void invalidSeverityRejected() {
        assertThat(detail(rejected(group("pores", "\"severity\":\"   \"")), "invalid"))
                .contains("pores.severity");
        assertThat(detail(rejected(group("pores", "\"severity\":7")), "invalid"))
                .contains("pores.severity");

        ReportNarrationScores scores = ReportNarrationScoreExtractor.extract(group("pores", ""));
        assertThat(scores.pores().severity()).isNull();
    }

    @Test
    @DisplayName("name 缺失/空白 → 422 invalid")
    void invalidNameRejected() {
        assertThat(detail(rejected(group("pores", "\"name\":\"  \"")), "invalid"))
                .contains("pores.name");
    }

    @Test
    @DisplayName("regions 缺失/空数组/非数组 → 422 invalid")
    void invalidRegionsRejected() {
        assertThat(detail(rejected(group("pores", "\"regions\":[]")), "invalid"))
                .contains("pores.regions");
        assertThat(detail(rejected(group("pores", "\"regions\":\"x\"")), "invalid"))
                .contains("pores.regions");
    }

    @Test
    @DisplayName("区域缺 name / score 非法 → 422 invalid 键路径")
    void invalidRegionRejected() {
        assertThat(detail(rejected(regionGroup("{\"region\":\"F\",\"score\":40}")), "invalid"))
                .contains("pores.regions[0].name");
        assertThat(detail(rejected(regionGroup("{\"region\":\"F\",\"name\":\"额\",\"score\":101}")), "invalid"))
                .contains("pores.regions[0].score");
    }

    @Test
    @DisplayName("未知键丢弃：抽取结果与仅含白名单字段的等价载荷一致")
    void unknownKeysDropped() {
        ReportNarrationScores withUnknown = ReportNarrationScoreExtractor.extract(
                "{\"pores\":{\"name\":\"n\",\"regions\":[{\"region\":\"F\",\"name\":\"额\"}],"
                        + "\"debug\":\"x\",\"raw_scores\":[1,2,3]},"
                        + "\"spots\":{\"name\":\"s\",\"regions\":[{\"region\":\"F\",\"name\":\"额\",\"extra\":9}]},"
                        + "\"surface_gloss\":{\"name\":\"g\",\"regions\":[{\"region\":\"F\",\"name\":\"额\"}]}}");
        ReportNarrationScores clean = ReportNarrationScoreExtractor.extract(
                "{\"pores\":{\"name\":\"n\",\"regions\":[{\"region\":\"F\",\"name\":\"额\"}]},"
                        + "\"spots\":{\"name\":\"s\",\"regions\":[{\"region\":\"F\",\"name\":\"额\"}]},"
                        + "\"surface_gloss\":{\"name\":\"g\",\"regions\":[{\"region\":\"F\",\"name\":\"额\"}]}}");
        assertThat(withUnknown).isEqualTo(clean);
    }

    @Test
    @DisplayName("区域零转换：区域码与顺序原样保留（不做 F/L/R 映射、不翻转、不重排）")
    void regionsAreNotTransformed() {
        ReportNarrationScores scores = ReportNarrationScoreExtractor.extract(
                "{\"pores\":{\"name\":\"n\",\"regions\":[{\"region\":\"nose\",\"name\":\"鼻部\"},"
                        + "{\"region\":\"perioral\",\"name\":\"口周\"}]},"
                        + "\"spots\":{\"name\":\"s\",\"regions\":[{\"region\":\"R\",\"name\":\"右脸\"},"
                        + "{\"region\":\"L\",\"name\":\"左脸\"}]},"
                        + "\"surface_gloss\":{\"name\":\"g\",\"regions\":[{\"region\":\"F\",\"name\":\"额头\"}]}}");
        assertThat(scores.pores().regions()).extracting(ReportNarrationScores.Region::region)
                .containsExactly("nose", "perioral");
        assertThat(scores.spots().regions()).extracting(ReportNarrationScores.Region::region)
                .containsExactly("R", "L");
    }

    private static String group(String groupName, String extraField) {
        String field = extraField.isEmpty() ? "" : "," + extraField;
        String regions = "\"regions\":[{\"region\":\"F\",\"name\":\"额\"}]";
        return "{"
                + "\"" + groupName + "\":{\"name\":\"n\"," + regions + field + "},"
                + "\"spots\":{\"name\":\"s\",\"regions\":[{\"region\":\"F\",\"name\":\"额\"}]},"
                + "\"surface_gloss\":{\"name\":\"g\",\"regions\":[{\"region\":\"F\",\"name\":\"额\"}]}}";
    }

    private static String regionGroup(String regionJson) {
        return "{"
