        List<Frame> frames = new ArrayList<>();
        String event = null;
        StringBuilder data = new StringBuilder();
        StringBuilder raw = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            raw.append(line).append('\n');
